const POOL_TOTAL_SIZE = 65535;
const PAGE_SIZE = 4096;
const BLOCK_SIZE = 1024;
const MAX_ALLOCATIONS = 256;
const MIN_ALLOC_SIZE = 16;
const METADATA_PER_BLOCK = 32;
const LOW_MEMORY_BLOCKS = 64;
const GUARD_VALUE = 255;
const SMALL_OBJECT_THRESHOLD = 128;

class MemoryPool {
  constructor() {
    this.pageCount = Math.floor(POOL_TOTAL_SIZE / PAGE_SIZE);
    this.blockCount = Math.floor((this.pageCount * PAGE_SIZE) / BLOCK_SIZE);
    this.blocks = new Array(this.blockCount).fill(null);
    this.guards = new Array(this.blockCount).fill(GUARD_VALUE);
    this.allocations = new Map();
    this.nextHandle = 1;
  }

  usableBlockSize() {
    return BLOCK_SIZE - METADATA_PER_BLOCK;
  }

  blocksNeeded(size) {
    if (size <= SMALL_OBJECT_THRESHOLD) return 1;
    return Math.ceil(size / this.usableBlockSize());
  }

  freeBlocks() {
    return this.blocks.reduce((n, owner) => (owner === null ? n + 1 : n), 0);
  }

  findRun(need) {
    let run = 0;
    for (let i = 0; i < this.blockCount; i++) {
      run = this.blocks[i] === null ? run + 1 : 0;
      if (run === need) return i - need + 1;
    }
    return -1;
  }

  allocate(size) {
    if (!Number.isInteger(size) || size < MIN_ALLOC_SIZE) {
      throw new RangeError(`request must be an integer of at least ${MIN_ALLOC_SIZE} bytes`);
    }
    if (this.allocations.size >= MAX_ALLOCATIONS) {
      throw new Error('allocation table exhausted');
    }
    const need = this.blocksNeeded(size);
    const start = this.findRun(need);
    if (start < 0) return null;
    const handle = this.nextHandle++;
    for (let i = start; i < start + need; i++) this.blocks[i] = handle;
    this.allocations.set(handle, { start, blocks: need, size });
    return handle;
  }

  free(handle) {
    const rec = this.allocations.get(handle);
    if (!rec) throw new Error(`unknown handle ${handle}`);
    for (let i = rec.start; i < rec.start + rec.blocks; i++) {
      if (this.guards[i] !== GUARD_VALUE) throw new Error(`corruption detected at block ${i}`);
      this.blocks[i] = null;
    }
    this.allocations.delete(handle);
    return rec.size;
  }

  report() {
    const free = this.freeBlocks();
    const used = this.blockCount - free;
    const lines = [
      `pages=${this.pageCount} blocks=${this.blockCount} slack=${POOL_TOTAL_SIZE - this.pageCount * PAGE_SIZE}B`,
      `live=${this.allocations.size}/${MAX_ALLOCATIONS} used=${used} free=${free} metadata=${used * METADATA_PER_BLOCK}B`
    ];
    if (free <= LOW_MEMORY_BLOCKS) lines.push(`WARNING: free blocks at or below ${LOW_MEMORY_BLOCKS}`);
    return lines.join('\n');
  }
}

function main() {
  const pool = new MemoryPool();
  const handles = [24, 96, 900, 5000, 3000].map(size => pool.allocate(size));
  console.log(pool.report());
  console.log(`released ${pool.free(handles[3])} bytes`);
  console.log(`refused oversize request: ${pool.allocate(POOL_TOTAL_SIZE) === null}`);
  console.log(pool.report());
}

main();

module.exports = { MemoryPool, POOL_TOTAL_SIZE, BLOCK_SIZE, PAGE_SIZE };

