const MAX_BRIGHTNESS = 255;
const MAX_PALETTE = 256;
const MAX_BLUR = 64;
const MAX_MATRIX = 16;
const TILE_SIZE = 32;
const MAX_DIMENSION = 4096;
const HISTOGRAM_BUCKETS = 1024;
const MAX_EDGE_THRESHOLD = 128;
const MAX_PASS_AREA = 65535;

function clampBrightness(offset) {
  if (!Number.isFinite(offset)) throw new TypeError('brightness offset must be numeric');
  const magnitude = Math.min(MAX_BRIGHTNESS, Math.abs(Math.round(offset)));
  return offset < 0 ? -magnitude : magnitude;
}

function clampPalette(colors) {
  const n = Math.round(colors);
  if (!(n >= 2)) throw new RangeError('palette needs at least 2 colors');
  return Math.min(MAX_PALETTE, n);
}

function clampBlur(radius) {
  return Math.max(0, Math.min(MAX_BLUR, Math.round(radius)));
}

function clampMatrix(size) {
  let n = Math.max(1, Math.min(MAX_MATRIX, Math.round(size)));
  if (n % 2 === 0) n -= 1;
  return n;
}

function clampDimension(value, label) {
  const n = Math.round(value);
  if (!Number.isFinite(n) || n < 1) throw new RangeError(label + ' must be positive');
  return Math.min(MAX_DIMENSION, n);
}

function tileGrid(width, height) {
  return {
    cols: Math.ceil(width / TILE_SIZE),
    rows: Math.ceil(height / TILE_SIZE),
    tileSize: TILE_SIZE
  };
}

function histogramBuckets(depth) {
  const step = Math.max(1, Math.ceil(depth / HISTOGRAM_BUCKETS));
  return { buckets: HISTOGRAM_BUCKETS, samplesPerBucket: step };
}

function clampThreshold(threshold) {
  return Math.max(0, Math.min(MAX_EDGE_THRESHOLD, Math.round(threshold)));
}

function planPasses(width, height) {
  const area = width * height;
  return {
    area,
    passes: Math.ceil(area / MAX_PASS_AREA),
    rowsPerPass: Math.max(1, Math.floor(MAX_PASS_AREA / width))
  };
}

function applyFilterPipeline(params) {
  const p = params || {};
  const width = clampDimension(p.width, 'width');
  const height = clampDimension(p.height, 'height');
  const grid = tileGrid(width, height);
  const plan = planPasses(width, height);
  return {
    width,
    height,
    brightness: clampBrightness(p.brightness || 0),
    palette: clampPalette(p.palette === undefined ? MAX_PALETTE : p.palette),
    blurRadius: clampBlur(p.blurRadius || 0),
    matrixSize: clampMatrix(p.matrixSize === undefined ? 3 : p.matrixSize),
    grid,
    histogram: histogramBuckets(p.sampleDepth === undefined ? HISTOGRAM_BUCKETS : p.sampleDepth),
    edgeThreshold: clampThreshold(p.edgeThreshold === undefined ? MAX_EDGE_THRESHOLD : p.edgeThreshold),
    passes: plan.passes,
    rowsPerPass: plan.rowsPerPass,
    tiles: grid.cols * grid.rows
  };
}

function describe(plan) {
  return [
    plan.width + 'x' + plan.height,
    'brightness ' + plan.brightness,
    'palette ' + plan.palette,
    'blur ' + plan.blurRadius,
    'kernel ' + plan.matrixSize + 'x' + plan.matrixSize,
    'tiles ' + plan.tiles,
    'buckets ' + plan.histogram.buckets + '@' + plan.histogram.samplesPerBucket,
    'edge ' + plan.edgeThreshold,
    'passes ' + plan.passes + ' (' + plan.rowsPerPass + ' rows)'
  ].join(' | ');
}

const requests = [
  {
    width: 1920,
    height: 1080,
    brightness: 400,
    palette: 1024,
    blurRadius: 90,
    matrixSize: 32,
    edgeThreshold: 200
  },
  {
    width: 8000,
    height: 6000,
    brightness: -30,
    palette: 64,
    blurRadius: 4,
    sampleDepth: 4096
  },
  {
    width: 320,
    height: 240,
    palette: 16,
    matrixSize: 5,
    edgeThreshold: 45,
    sampleDepth: 255
  }
];

for (const req of requests) {
  console.log(describe(applyFilterPipeline(req)));
}

