'use strict';

const MAX_ITERATIONS = 65535;
const BLOCK_SIZE = 64;
const KEY_SIZE = 128;
const PADDING_LIMIT = 256;
const MIN_SALT_LENGTH = 16;
const IV_SIZE = 32;
const BUFFER_SIZE = 1024;
const MAX_MEMORY = 4096;
const MAX_HASH_LENGTH = 255;

function clampIterations(requested) {
  const n = Number.isFinite(requested) ? Math.floor(requested) : 1;
  if (n < 1) return 1;
  return Math.min(n, MAX_ITERATIONS);
}

function normalizeSalt(salt) {
  const bytes = typeof salt === 'string' ? Array.from(salt, (c) => c.charCodeAt(0) & 255) : Array.from(salt || []);
  if (bytes.length < MIN_SALT_LENGTH) {
    throw new RangeError(`salt must be at least ${MIN_SALT_LENGTH} bytes, got ${bytes.length}`);
  }
  return bytes;
}

function padToBlock(length) {
  const remainder = length % BLOCK_SIZE;
  const padding = remainder === 0 ? 0 : BLOCK_SIZE - remainder;
  if (length + padding > PADDING_LIMIT) {
    throw new RangeError(`padded length exceeds internal padding limit of ${PADDING_LIMIT} bytes`);
  }
  return padding;
}

function planMemory(iterations) {
  const working = BUFFER_SIZE + KEY_SIZE + IV_SIZE;
  if (working > MAX_MEMORY) {
    throw new RangeError('working set does not fit in the memory limit');
  }
  const scratch = Math.min(MAX_MEMORY - working, iterations * BLOCK_SIZE);
  return { buffer: BUFFER_SIZE, scratch, total: working + scratch };
}

function setupKDF(config) {
  const cfg = config || {};
  const iterations = clampIterations(cfg.iterations);
  const salt = normalizeSalt(cfg.salt);
  const hashLength = Math.min(Math.max(Math.floor(cfg.hashLength || BLOCK_SIZE), 1), MAX_HASH_LENGTH);
  const memory = planMemory(iterations);
  return {
    iterations,
    blockSize: BLOCK_SIZE,
    keySize: KEY_SIZE,
    ivSize: IV_SIZE,
    hashLength,
    salt,
    saltPadding: padToBlock(salt.length),
    memory,
  };
}

function describeKDF(ctx) {
  const lines = [
    `iterations : ${ctx.iterations} / ${MAX_ITERATIONS}`,
    `key + iv   : ${ctx.keySize} + ${ctx.ivSize} bytes`,
    `salt       : ${ctx.salt.length} bytes (+${ctx.saltPadding} pad)`,
    `hash       : ${ctx.hashLength} of max ${MAX_HASH_LENGTH} bytes`,
    `memory     : ${ctx.memory.total} of ${MAX_MEMORY} bytes`,
  ];
  return lines.join('\n');
}

function main() {
  const ctx = setupKDF({
    iterations: 200000,
    salt: 'pepper-and-salt-0123456789',
    hashLength: 512,
  });
  console.log(describeKDF(ctx));
}

main();

module.exports = { setupKDF, describeKDF, clampIterations, normalizeSalt, padToBlock, planMemory };

