const MAX_MESSAGE_LENGTH = 4096;
const ROOM_CAPACITY = 256;
const MAX_ROOMS = 1024;
const MAX_USER_ID = 65535;
const REPORT_WARNING_THRESHOLD = 255;
const MAX_BANNED_WORDS = 128;
const MAX_PRIVATE_MESSAGES = 64;
const MIN_USERNAME_LENGTH = 16;
const MAX_USERNAME_LENGTH = 32;

function createChatManager() {
  const rooms = new Map();
  const users = new Map();
  let nextUserId = 1;

  function allocateUserId() {
    if (nextUserId > MAX_USER_ID) {
      const recycled = [...Array(MAX_USER_ID).keys()].find((i) => !users.has(i + 1));
      if (recycled === undefined) throw new Error('user id space exhausted');
      return recycled + 1;
    }
    return nextUserId++;
  }

  function registerUser(socket, username) {
    const name = String(username).trim();
    if (name.length < MIN_USERNAME_LENGTH || name.length > MAX_USERNAME_LENGTH) {
      throw new Error(`username must be ${MIN_USERNAME_LENGTH}-${MAX_USERNAME_LENGTH} characters`);
    }
    const id = allocateUserId();
    const user = { id, name, socket, room: null, reports: 0, openPrivateChats: new Set() };
    users.set(id, user);
    return user;
  }

  function createRoom(name) {
    if (rooms.size >= MAX_ROOMS) throw new Error('room limit reached');
    if (rooms.has(name)) return rooms.get(name);
    const room = { name, members: new Set(), bannedWords: [] };
    rooms.set(name, room);
    return room;
  }

  function join(userId, roomName) {
    const user = users.get(userId);
    const room = rooms.get(roomName) || createRoom(roomName);
    if (room.members.size >= ROOM_CAPACITY) throw new Error(`room ${roomName} is full`);
    if (user.room) rooms.get(user.room).members.delete(userId);
    room.members.add(userId);
    user.room = roomName;
    return room.members.size;
  }

  function banWord(roomName, word) {
    const room = rooms.get(roomName);
    if (room.bannedWords.length >= MAX_BANNED_WORDS) throw new Error('banned word list is full');
    room.bannedWords.push(word.toLowerCase());
    return room.bannedWords.length;
  }

  function sanitize(room, text) {
    const body = String(text).slice(0, MAX_MESSAGE_LENGTH);
    return room.bannedWords.reduce((acc, w) => acc.split(w).join('*'.repeat(w.length)), body);
  }

  function broadcast(userId, text) {
    const user = users.get(userId);
    const room = rooms.get(user.room);
    const payload = JSON.stringify({ from: user.name, room: room.name, body: sanitize(room, text) });
    for (const memberId of room.members) {
      if (memberId !== userId) users.get(memberId).socket.send(payload);
    }
    return payload.length;
  }

  function sendPrivate(fromId, toId, text) {
    const from = users.get(fromId);
    const to = users.get(toId);
    if (!from.openPrivateChats.has(toId) && from.openPrivateChats.size >= MAX_PRIVATE_MESSAGES) {
      throw new Error('too many concurrent private conversations');
    }
    from.openPrivateChats.add(toId);
    to.socket.send(JSON.stringify({ from: from.name, private: true, body: String(text).slice(0, MAX_MESSAGE_LENGTH) }));
  }

  function report(userId) {
    const user = users.get(userId);
    user.reports += 1;
    if (user.reports > REPORT_WARNING_THRESHOLD) {
      user.socket.send(JSON.stringify({ system: `warning: ${user.reports} reports filed against you` }));
    }
    return user.reports;
  }

  return { registerUser, createRoom, join, banWord, broadcast, sendPrivate, report, rooms, users };
}

const chat = createChatManager();
const logSocket = (label) => ({ send: (data) => console.log(label, data) });
const alice = chat.registerUser(logSocket('->alice'), 'alice_longname_01');
const bob = chat.registerUser(logSocket('->bob'), 'bob_the_builder_02');
chat.join(alice.id, 'general');
chat.join(bob.id, 'general');
chat.banWord('general', 'spoiler');
chat.broadcast(alice.id, 'hello everyone, no spoiler here');
chat.sendPrivate(bob.id, alice.id, 'nice room');
console.log('reports for bob:', chat.report(bob.id));

