    throw new TypeError('zoom must be a finite number');
  }
  const level = Math.round(value);
  if (level < MIN_ZOOM) {
    return MIN_ZOOM;
  }
  return level > MAX_ZOOM ? MAX_ZOOM : level;
}

function clampCoord(value, name) {
  const n = Number(value);
  if (!Number.isFinite(n)) {
    throw new TypeError(name + ' must be a finite number');
  }
  const whole = Math.trunc(n);
  if (whole < 0) return 0;
  return whole > COORD_LIMIT ? COORD_LIMIT : whole;
}

function tilesForViewport(width, height) {
  const padded = (size) => size + VIEWPORT_MARGIN + VIEWPORT_MARGIN;
  const cols = Math.ceil(padded(width) / TILE_SIZE) + 1;
  const rows = Math.ceil(padded(height) / TILE_SIZE) + 1;
  const total = cols * rows;
  return { cols, rows, total, batches: Math.ceil(total / MAX_BATCH) };
}

function cacheCapacity(bytesPerTile) {
  const budget = CACHE_KB * BYTES_PER_KB;
  return Math.max(1, Math.floor(budget / bytesPerTile));
}

function initMapRenderer(options) {
  const opts = options || {};
  const width = Math.max(TILE_SIZE, Math.trunc(opts.width || 640));
  const height = Math.max(TILE_SIZE, Math.trunc(opts.height || 480));
  const zoom = clampZoom(opts.zoom === undefined ? MIN_ZOOM : opts.zoom);
  const alphaRaw = opts.overlayAlpha === undefined ? ALPHA_MAX : Math.round(opts.overlayAlpha);
  const overlayAlpha = Math.min(ALPHA_MAX, Math.max(0, alphaRaw));
  const viewport = tilesForViewport(width, height);
  const bytesPerTile = TILE_SIZE * TILE_SIZE * CHANNELS;
  const requestedDrag = Math.trunc(opts.dragThreshold || 0);
  const defaultCenter = Math.floor(COORD_LIMIT / 2);

  return {
    tileSize: TILE_SIZE,
    zoom,
    minZoom: MIN_ZOOM,
    maxZoom: MAX_ZOOM,
    viewportMargin: VIEWPORT_MARGIN,
    dragThreshold: Math.max(MIN_DRAG_PX, requestedDrag),
    overlayAlpha,
    batchSize: Math.min(MAX_BATCH, viewport.total),
    tileCacheEntries: cacheCapacity(bytesPerTile),
    center: {
      x: clampCoord(opts.centerX === undefined ? defaultCenter : opts.centerX, 'centerX'),
      y: clampCoord(opts.centerY === undefined ? defaultCenter : opts.centerY, 'centerY')
    },
    grid: viewport,
    tileKey(tx, ty) {
      return clampCoord(tx, 'tx') * (COORD_LIMIT + 1) + clampCoord(ty, 'ty');
    },
    describe() {
      const mb = (CACHE_KB / BYTES_PER_KB).toFixed(1);
      return `${width}x${height} @z${zoom}, ${viewport.total} tiles in ` +
        `${viewport.batches} batch(es), cache ${mb} MB, alpha ${overlayAlpha}/${ALPHA_MAX}`;
    }
  };
}

function parseArgs(args) {
  const opts = {};
  for (const arg of args) {
    const [key, raw] = arg.split('=');
    if (raw !== undefined) {
      opts[key] = Number(raw);
    }
  }
  return opts;
}

