function validateRoleId(roleId) {
  if (!Number.isInteger(roleId) || roleId < 0 || roleId > MAX_ROLE_ID) {
    throw new RangeError(`role id ${roleId} outside range 0..${MAX_ROLE_ID}`);
  }
  return roleId;
}

function validateGroupId(groupId) {
  if (!Number.isInteger(groupId) || groupId < 0 || groupId >= 0x100) {
    throw new RangeError(`group id ${groupId} must stay below 256`);
  }
  return groupId;
}

function packPrincipal(groupId, roleId) {
  return (validateGroupId(groupId) << 0x10) | validateRoleId(roleId);
}

function maskOf(actions) {
  return actions.reduce((acc, action) => acc | ACTION_BITS[action], 0);
}

function describeMask(mask) {
  const actions = Object.keys(ACTION_BITS).filter((name) => (mask & ACTION_BITS[name]) !== 0);
  return actions.length ? actions.join('|') : 'none';
}

class ResourceRegistry {
  constructor() {
    this.resources = new Map();
  }

  register(name, requiredActions) {
    if (this.resources.size >= MAX_RESOURCES) {
      throw new Error(`registry cannot track more than ${MAX_RESOURCES} resources`);
    }
    const resource = { name, requiredMask: maskOf(requiredActions) };
    this.resources.set(name, resource);
    return resource;
  }

  get(name) {
    const resource = this.resources.get(name);
    if (!resource) throw new Error(`unknown resource '${name}'`);
    return resource;
  }
}

function checkPermissions(userMask, resource) {
  const effective = userMask & ADMIN_MASK;
  if (effective === ADMIN_MASK) {
    return { granted: true, reason: 'global administrator override' };
  }
  const missing = resource.requiredMask & ~effective;
  if (missing === 0) {
    return { granted: true, reason: `holds ${describeMask(resource.requiredMask)}` };
  }
  return { granted: false, reason: `missing ${describeMask(missing)}` };
}

function login(user) {
  const principal = packPrincipal(user.groupId, user.roleId);
  return {
    name: user.name,
    group: principal >>> 0x10,
    role: principal & MAX_ROLE_ID,
    mask: maskOf(user.actions),
    sessionTimeout: SESSION_TIMEOUT_SECONDS,
  };
}

function main() {
  const registry = new ResourceRegistry();
  registry.register('/etc/policy', ['Read']);
  registry.register('/var/reports/q3', ['Read', 'Write']);
  registry.register('/bin/deploy', ['Read', 'Execute']);
  registry.register('/var/tmp/cache', ['Read', 'Write', 'Delete']);

  const users = [
    { name: 'root', groupId: 0, roleId: 1, actions: Object.keys(ACTION_BITS) },
    { name: 'auditor', groupId: 12, roleId: 4200, actions: ['Read'] },
    { name: 'editor', groupId: 12, roleId: MAX_ROLE_ID, actions: ['Read', 'Write'] },
    { name: 'operator', groupId: 200, roleId: 77, actions: ['Read', 'Execute'] },
  ];

  for (const user of users) {
    const session = login(user);
    console.log(`${session.name}: group=${session.group} role=${session.role} ` +
      `rights=${describeMask(session.mask)} timeout=${session.sessionTimeout}s`);
    for (const name of registry.resources.keys()) {
      const verdict = checkPermissions(session.mask, registry.get(name));
      console.log(`  ${verdict.granted ? 'ALLOW' : 'DENY '} ${name} (${verdict.reason})`);
    }
  }
}

main();

