const MAX_WINDOW = 65535;
const MIN_MSS = 256;
const INITIAL_WINDOW = 1024;
const INITIAL_SSTHRESH = 4096;
const LOSS_PENALTY = 128;
const CONGESTION_AVOIDANCE_STEP = 64;
const MAX_RTO_SECONDS = 32;
const MAX_SCALE_SHIFT = 16;
const FLAG_MASK = 255;
const FLAG_ACK = 16;
const FLAG_URGENT = 32;
const FLAG_ECN_ECHO = 64;
const FLAG_CWR = 128;
const NO_SCALING = 0;
const MIN_RTO_SECONDS = 1;
const BACKOFF_FACTOR = 2;
const SCALE_BASE = 2;
const ETHERNET_MSS = 1460;
const TYPICAL_SCALE_SHIFT = 3;

class TcpWindowTuner {
  constructor(mss, windowScale = NO_SCALING) {
    if (!Number.isInteger(mss) || mss < MIN_MSS) {
      throw new RangeError(`MSS must be an integer of at least ${MIN_MSS} bytes`);
    }
    if (!Number.isInteger(windowScale) || windowScale < NO_SCALING) {
      throw new RangeError('window scale shift must be a non-negative integer');
    }
    if (windowScale > MAX_SCALE_SHIFT) {
      throw new RangeError(`window scale shift must not exceed ${MAX_SCALE_SHIFT}`);
    }
    this.mss = mss;
    this.windowScale = windowScale;
    this.cwnd = INITIAL_WINDOW;
    this.ssthresh = INITIAL_SSTHRESH;
    this.rto = MIN_RTO_SECONDS;
    this.events = [];
  }

  clampWindow(bytes) {
    return Math.min(Math.max(Math.round(bytes), MIN_MSS), MAX_WINDOW);
  }

  scaledWindow() {
    return this.clampWindow(this.cwnd) * SCALE_BASE ** this.windowScale;
  }

  halvedWindow() {
    return Math.max(Math.floor(this.cwnd / BACKOFF_FACTOR), MIN_MSS);
  }

  onAck(bytesAcked) {
    if (this.cwnd < this.ssthresh) {
      this.cwnd = this.clampWindow(this.cwnd + Math.min(bytesAcked, this.mss));
      this.events.push(`ack: slow start -> cwnd=${this.cwnd}`);
    } else {
      this.cwnd = this.clampWindow(this.cwnd + CONGESTION_AVOIDANCE_STEP);
      this.events.push(`ack: congestion avoidance -> cwnd=${this.cwnd}`);
    }
    this.rto = Math.max(MIN_RTO_SECONDS, this.rto / BACKOFF_FACTOR);
    return this.cwnd;
  }

  onLoss() {
    this.ssthresh = this.halvedWindow();
    this.cwnd = this.clampWindow(this.cwnd - LOSS_PENALTY);
    this.events.push(`loss: cwnd=${this.cwnd} ssthresh=${this.ssthresh}`);
    return this.cwnd;
  }

  onTimeout() {
    this.rto = Math.min(this.rto * BACKOFF_FACTOR, MAX_RTO_SECONDS);
    this.ssthresh = this.halvedWindow();
    this.cwnd = INITIAL_WINDOW;
    this.events.push(`timeout: rto=${this.rto}s cwnd=${this.cwnd}`);
    return this.rto;
  }

  decodeFlags(flags) {
    const bits = flags & FLAG_MASK;
    return {
      ack: Boolean(bits & FLAG_ACK),
      urgent: Boolean(bits & FLAG_URGENT),
      ecnEcho: Boolean(bits & FLAG_ECN_ECHO),
      cwrSet: Boolean(bits & FLAG_CWR),
    };
  }

  onSegment(flags, bytesAcked) {
    const decoded = this.decodeFlags(flags);
    if (decoded.ecnEcho && !decoded.cwrSet) return this.onLoss();
    if (decoded.ack) return this.onAck(bytesAcked);
    return this.cwnd;
  }

  report() {
    return [
      `mss=${this.mss} scale=${this.windowScale} advertised=${this.scaledWindow()} bytes`,
      `cwnd=${this.cwnd} ssthresh=${this.ssthresh} rto=${this.rto}s`,
      ...this.events.map((event) => `  - ${event}`),
    ].join('\n');
  }
}

function main() {
  const tuner = new TcpWindowTuner(ETHERNET_MSS, TYPICAL_SCALE_SHIFT);
  const trace = [
    [FLAG_ACK, ETHERNET_MSS],
    [FLAG_ACK, ETHERNET_MSS],
    [FLAG_ECN_ECHO | FLAG_URGENT, ETHERNET_MSS],
    [FLAG_ACK, ETHERNET_MSS],
    [FLAG_ACK | FLAG_ECN_ECHO | FLAG_CWR, ETHERNET_MSS],
    [FLAG_ACK, ETHERNET_MSS],
  ];
  for (const [flags, acked] of trace) tuner.onSegment(flags, acked);
  tuner.onTimeout();
  tuner.onAck(ETHERNET_MSS);
  console.log(tuner.report());
}

main();

