const MAX_ABS_COORD = 0xFFFF;
const MAX_NODES = 0x400;
const CURVE_SAMPLES = 0x100;
const MAX_CONTROL_DISTANCE = 0x80;
const OPACITY_STEPS = 0xFF;
const MAX_GROUP_DEPTH = 0x10;
const MAX_STROKE_WIDTH = 0x20;
const TIME_BUDGET_MS = 0x1000;
const FLATTEN_ANGLE_DEG = 0x40;

function parsePath(d) {
  const tokens = d.match(/[MLCZ]|-?\d*\.?\d+/gi) || [];
  const nodes = [];
  let cmd = 'M', i = 0;
  while (i < tokens.length) {
    if (/[MLCZ]/i.test(tokens[i])) cmd = tokens[i++].toUpperCase();
    if (cmd === 'Z') { nodes.push({ type: 'Z' }); continue; }
    const count = cmd === 'C' ? 6 : 2;
    const nums = tokens.slice(i, i + count).map(Number);
    i += count;
