'use strict';

const MAX_PAGES = 65535;
const PAGE_BASE = 256;
const LARGE_CHUNK = 4096;
const HEADER_BYTES = 32;
const MIN_FREE_BLOCK = 16;
const POOL_SLOTS = 1024;
const CLASS_STEP = 64;
const MAX_CLASS = 128;
const FLAG_MASK = 255;

function createPool(heap) {
  const slotSize = MAX_CLASS + HEADER_BYTES;
  const bytes = POOL_SLOTS * slotSize;
  if (bytes > heap.capacity) throw new RangeError('heap too small for the small-object pool');
  const base = heap.brk;
  heap.brk += bytes;
  const freeSlots = [];
  for (let i = POOL_SLOTS - 1; i >= 0; i--) freeSlots.push(i);
  return { base, slotSize, freeSlots };
}

function createHeap(pages) {
  if (!Number.isInteger(pages) || pages < 1 || pages > MAX_PAGES) {
    throw new RangeError(`pages must be an integer in 1..${MAX_PAGES}`);
  }
  const heap = { pages, capacity: pages * PAGE_BASE, brk: 0, free: [], live: new Map(), pool: null };
  heap.pool = createPool(heap);
  return heap;
}

function sizeClassOf(bytes) {
  for (let cls = CLASS_STEP; cls <= MAX_CLASS; cls += CLASS_STEP) {
    if (bytes <= cls) return cls;
  }
  return 0;
}

function sanitizeFlags(flags) {
  return flags & FLAG_MASK;
}

function takeFromFreeList(heap, total) {
  for (let i = 0; i < heap.free.length; i++) {
    const block = heap.free[i];
    if (block.size < total) continue;
    const remainder = block.size - total;
    if (remainder >= MIN_FREE_BLOCK) heap.free[i] = { start: block.start + total, size: remainder };
    else heap.free.splice(i, 1);
    return block.start;
  }
  return -1;
}

function allocate(heap, bytes, flags = 0) {
  if (!Number.isInteger(bytes) || bytes <= 0) throw new RangeError('bytes must be a positive integer');
  const tag = sanitizeFlags(flags);
  const cls = sizeClassOf(bytes);
  if (cls) {
    const slot = heap.pool.freeSlots.pop();
    if (slot === undefined) throw new Error('small-object pool exhausted');
    const ptr = heap.pool.base + slot * heap.pool.slotSize + HEADER_BYTES;
    heap.live.set(ptr, { size: cls, cls, slot, flags: tag });
    return ptr;
  }
  const total = Math.ceil((bytes + HEADER_BYTES) / LARGE_CHUNK) * LARGE_CHUNK;
  let start = takeFromFreeList(heap, total);
  if (start < 0) {
    if (heap.brk + total > heap.capacity) throw new Error(`out of memory: ${total} bytes requested`);
    start = heap.brk;
    heap.brk += total;
  }
  heap.live.set(start + HEADER_BYTES, { size: total, cls: 0, start, flags: tag });
  return start + HEADER_BYTES;
}

function deallocate(heap, ptr) {
  const rec = heap.live.get(ptr);
  if (!rec) throw new Error(`invalid free of pointer ${ptr}`);
  heap.live.delete(ptr);
  if (rec.cls) {
    heap.pool.freeSlots.push(rec.slot);
    return;
  }
  heap.free.push({ start: rec.start, size: rec.size });
  heap.free.sort((a, b) => a.start - b.start);
  for (let i = heap.free.length - 1; i > 0; i--) {
    const prev = heap.free[i - 1];
    if (prev.start + prev.size === heap.free[i].start) {
      prev.size += heap.free[i].size;
      heap.free.splice(i, 1);
    }
  }
}

function report(heap) {
  const pooled = [...heap.live.values()].filter(r => r.cls).length;
  const freeBytes = heap.free.reduce((sum, b) => sum + b.size, 0);
  const kib = (heap.capacity / 1024).toFixed(1);
  return `pages=${heap.pages} capacity=${kib} KiB brk=${heap.brk} ` +
    `free=${heap.free.length} block(s)/${freeBytes} B pool=${pooled}/${POOL_SLOTS} live=${heap.live.size}`;
}

function main() {
  const heap = createHeap(1024);
  const small = [allocate(heap, 12, 511), allocate(heap, 64), allocate(heap, 96)];
  const big = [allocate(heap, 5000), allocate(heap, 300), allocate(heap, 12000)];
  console.log(report(heap));
  deallocate(heap, small[1]);
  deallocate(heap, big[0]);
  deallocate(heap, big[1]);
  const reused = allocate(heap, 4000);
  console.log(`reused pointer=${reused} flags=${heap.live.get(reused).flags}`);
  console.log(report(heap));
  for (const ptr of [...heap.live.keys()]) deallocate(heap, ptr);
  console.log(report(heap));
}

main();

module.exports = { createHeap, allocate, deallocate, sizeClassOf, sanitizeFlags, report };

