function parseRecord(line) {
  const parts = line.trim().split(',');
  if (parts.length !== 4) return null;
  const [symbol, priceCents, volume, tsMs] = parts;
  const rec = {
    symbol: symbol.toUpperCase(),
    priceCents: Number(priceCents),
    volume: Number(volume),
    tsMs: Number(tsMs)
  };
  if (!rec.symbol || !Number.isFinite(rec.priceCents) || !Number.isFinite(rec.volume)) return null;
  if (!Number.isFinite(rec.tsMs)) return null;
  return rec;
}

class FeedParser {
  constructor() {
    this.tail = '';
    this.rejected = 0;
  }
  push(chunk) {
    const lines = (this.tail + chunk).split('\n');
    this.tail = lines.pop();
    const records = [];
    for (const line of lines) {
      const rec = parseRecord(line);
      if (rec) records.push(rec);
      else if (line.trim()) this.rejected++;
    }
    return records;
  }
}

