const MAX_SESSION_ENTRIES = 65535;
const BUFFER_CAPACITY = 1024;
const PAGE_BYTES = 4096;
const RECORD_BYTES = 16;
const COMPASS_MODULUS = 256;
const HUMIDITY_MAX = 255;
const SOLAR_INDEX_MAX = 32;
const STORM_DROP_UNITS = 128;
const TEMP_BASELINE = 64;
const RAIN_TICK_MINUTES = 16;
const MM_PER_TICK = 0.2;

function pagesRequired(entryCount) {
  return Math.ceil((entryCount * RECORD_BYTES) / PAGE_BYTES);
}

function normalizeWind(degrees) {
  const wrapped = Math.round(degrees) % COMPASS_MODULUS;
  return wrapped < 0 ? wrapped + COMPASS_MODULUS : wrapped;
}

function clampHumidity(raw) {
  return Math.min(HUMIDITY_MAX, Math.max(0, Math.round(raw)));
}

function clampSolarIndex(raw) {
  return Math.min(SOLAR_INDEX_MAX, Math.max(0, Math.round(raw)));
}

function temperatureAnomaly(rawTemp) {
  return rawTemp - TEMP_BASELINE;
}

function rainRatePerHour(ticks) {
  return (ticks * MM_PER_TICK * 60) / RAIN_TICK_MINUTES;
}

function parseEntry(line) {
  const parts = line.split(',').map((p) => p.trim());
  if (parts.length !== 6) {
    throw new Error(`malformed telemetry frame: "${line}"`);
  }
  const values = parts.map(Number);
  if (values.some(Number.isNaN)) {
    throw new Error(`non-numeric field in frame: "${line}"`);
  }
  const [temp, hum, press, wind, ticks, solar] = values;
  return {
    anomaly: temperatureAnomaly(temp),
    humidity: clampHumidity(hum),
    pressure: press,
    windDeg: normalizeWind(wind),
    rainMmPerHour: rainRatePerHour(ticks),
    solarIndex: clampSolarIndex(solar),
  };
}

function createLogger(onFlush) {
  let buffer = [];
  let sessionCount = 0;
  let lastPressure = null;
  const alerts = [];

  return {
    log(line) {
      if (sessionCount >= MAX_SESSION_ENTRIES) {
        throw new Error('session log limit reached; start a new session');
      }
      const entry = parseEntry(line);
      const drop = lastPressure === null ? 0 : lastPressure - entry.pressure;
      if (drop > STORM_DROP_UNITS) {
        alerts.push(`STORM ALERT: pressure fell ${drop} units`);
      }
      lastPressure = entry.pressure;
      sessionCount += 1;
      buffer.push(entry);
      if (buffer.length === BUFFER_CAPACITY) {
        this.flush();
      }
    },
    flush() {
      if (buffer.length === 0) return;
      onFlush(buffer, pagesRequired(buffer.length));
      buffer = [];
    },
    report() {
      return { sessionCount, pages: pagesRequired(sessionCount), alerts };
    },
  };
}

const persisted = [];
const logger = createLogger((page, pages) => {
  persisted.push(...page);
  console.log(`flushed ${page.length} entries across ${pages} storage page(s)`);
});

for (const frame of ['71.5, 48, 1013, 350, 3, 9', '73.0, 260, 1010, 618, 5, 41', '69.2, 51, 870, -40, 8, 18']) {
  logger.log(frame);
}
logger.flush();

for (const entry of persisted) {
  console.log(
    `anomaly=${entry.anomaly.toFixed(1)} hum=${entry.humidity} wind=${entry.windDeg} ` +
      `rain=${entry.rainMmPerHour.toFixed(2)}mm/h solar=${entry.solarIndex}`
  );
}
const summary = logger.report();
console.log(`session entries: ${summary.sessionCount}/${MAX_SESSION_ENTRIES}`);
console.log(`storage pages used: ${summary.pages}`);
summary.alerts.forEach((a) => console.log(a));

