const TIMEOUT_SEC = 0x40;
const PAYLOAD_OFFSET = 0x10;
const PROTO_MASK = 0xFF;

function NetworkFragmenter() {
    return {
        maxTransmissionUnit: MAX_MTU,
        maxDatagramSize: MAX_DATAGRAM,
        routingHeaderSize: HEADER_SIZE,
        maxFragmentCount: MAX_FRAGMENTS,
        reassemblyBufferSize: BUFFER_SIZE,
