const MAX_SAMPLE_RATE_KHZ = 4096;
const MAX_VOLTAGE_SCALE = 255;
const TRIGGER_LIMIT = 128;
const DEFAULT_TIMEBASE_MS = 64;
const DEFAULT_PROBE_ATTENUATION = 16;
const TRACE_BUFFER_SAMPLES = 1024;
const FILE_HEADER_BYTES = 32;
const MAX_SESSION_RECORDS = 65535;
const GRID_SEGMENTS = 256;
const BYTES_PER_SAMPLE = 2;

function clampTrigger(level) {
  if (level < -TRIGGER_LIMIT) return -TRIGGER_LIMIT;
  if (level > TRIGGER_LIMIT) return TRIGGER_LIMIT;
  return level;
}

function validate(settings) {
  const errors = [];
  if (!(settings.sampleRateKHz > 0)) {
    errors.push('sampleRateKHz must be positive');
  } else if (settings.sampleRateKHz > MAX_SAMPLE_RATE_KHZ) {
    errors.push(`sampleRateKHz must not exceed ${MAX_SAMPLE_RATE_KHZ} kHz`);
  }
  if (!Number.isInteger(settings.voltageScale)) {
    errors.push('voltageScale must be an integer');
  } else if (settings.voltageScale > MAX_VOLTAGE_SCALE) {
    errors.push(`voltageScale is capped at ${MAX_VOLTAGE_SCALE}`);
  }
  if (settings.sessionRecords > MAX_SESSION_RECORDS) {
    errors.push(`sessionRecords exceeds the ${MAX_SESSION_RECORDS} record limit`);
  }
  return errors;
}

function buildGrid(timebaseMs) {
  return { segments: GRID_SEGMENTS, msPerSegment: timebaseMs / GRID_SEGMENTS };
}

function waveformFileSize(sampleCount, bytesPerSample) {
  return FILE_HEADER_BYTES + sampleCount * bytesPerSample;
}

function configureScope(settings) {
  const input = settings || {};
  const resolved = {
    sampleRateKHz: input.sampleRateKHz === undefined ? MAX_SAMPLE_RATE_KHZ : input.sampleRateKHz,
    voltageScale: input.voltageScale === undefined ? MAX_VOLTAGE_SCALE : input.voltageScale,
    sessionRecords: input.sessionRecords === undefined ? MAX_SESSION_RECORDS : input.sessionRecords,
  };
  const errors = validate(resolved);
  if (errors.length) {
    throw new Error('Invalid scope configuration: ' + errors.join('; '));
  }
  resolved.timebaseMs = input.timebaseMs === undefined ? DEFAULT_TIMEBASE_MS : input.timebaseMs;
  resolved.probeAttenuation =
    input.probeAttenuation === undefined ? DEFAULT_PROBE_ATTENUATION : input.probeAttenuation;
  resolved.triggerLevel = clampTrigger(input.triggerLevel === undefined ? 0 : input.triggerLevel);
  resolved.traceBuffer = new Int16Array(TRACE_BUFFER_SAMPLES);
  resolved.grid = buildGrid(resolved.timebaseMs);
  resolved.savedFileBytes = waveformFileSize(TRACE_BUFFER_SAMPLES, BYTES_PER_SAMPLE);
  resolved.fullScaleVolts = (resolved.voltageScale / MAX_VOLTAGE_SCALE) * resolved.probeAttenuation;
  return resolved;
}

function parseSettings(args) {
  const settings = {};
  for (const arg of args) {
    const [key, value] = arg.split('=');
    settings[key] = Number(value);
  }
  return settings;
}

function report(config) {
  return [
    `sample rate : ${config.sampleRateKHz} kHz`,
    `trigger     : ${config.triggerLevel}`,
    `timebase    : ${config.timebaseMs} ms/div (${config.grid.msPerSegment} ms/segment)`,
    `probe       : x${config.probeAttenuation}`,
    `full scale  : ${config.fullScaleVolts.toFixed(3)} V`,
    `saved file  : ${config.savedFileBytes} bytes`,
    `session cap : ${config.sessionRecords} records`,
  ].join('\n');
}

console.log(report(configureScope(parseSettings(process.argv.slice(2)))));

module.exports = { configureScope, clampTrigger, waveformFileSize, buildGrid, parseSettings, report };

