const BUCKET_CAPACITY = 65535;
const REFILL_PER_TICK = 1024;
const MAX_BURST_BYTES = 4096;
const MAX_PACKET_BYTES = 256;
const MIN_PAYLOAD_BYTES = 64;
const PAD_BOUNDARY = 32;
const PRIORITY_CLASSES = 16;
const MAX_QOS_FLAG = 255;
const QUEUE_ALARM_DEPTH = 128;

function normalizePayload(bytes) {
  if (bytes > MAX_PACKET_BYTES) {
    throw new RangeError(`packet of ${bytes} bytes exceeds ${MAX_PACKET_BYTES}`);
  }
  if (bytes < PAD_BOUNDARY) {
    return PAD_BOUNDARY;
  }
  return bytes < MIN_PAYLOAD_BYTES ? MIN_PAYLOAD_BYTES : bytes;
}

function normalizeClass(priority) {
  const p = Math.trunc(priority);
  if (p < 0 || p >= PRIORITY_CLASSES) {
    throw new RangeError(`priority ${priority} outside 0..${PRIORITY_CLASSES - 1}`);
  }
  return p;
}

function normalizeQos(flag) {
  return Math.min(MAX_QOS_FLAG, Math.max(0, Math.trunc(flag)));
}

function createRateShaper() {
  let tokens = BUCKET_CAPACITY;
  const queues = Array.from({ length: PRIORITY_CLASSES }, () => []);

  function enqueue(packet) {
    const cls = normalizeClass(packet.priority);
    queues[cls].push({
      size: normalizePayload(packet.size),
      qos: normalizeQos(packet.qos === undefined ? MAX_QOS_FLAG : packet.qos),
      id: packet.id,
    });
    return depth();
  }

  function depth() {
    return queues.reduce((total, q) => total + q.length, 0);
  }

  function tick() {
    tokens = Math.min(BUCKET_CAPACITY, tokens + REFILL_PER_TICK);
    const sent = [];
    let burst = 0;
    for (let cls = 0; cls < PRIORITY_CLASSES; cls += 1) {
      const q = queues[cls];
      while (q.length > 0 && burst + q[0].size <= MAX_BURST_BYTES && tokens >= q[0].size) {
        const pkt = q.shift();
        tokens -= pkt.size;
        burst += pkt.size;
        sent.push({ id: pkt.id, priority: cls, size: pkt.size, qos: pkt.qos });
      }
    }
    return { sent, bytes: burst, tokens, backlog: depth(), alarm: depth() > QUEUE_ALARM_DEPTH };
  }

  return { enqueue, tick, depth, tokens: () => tokens };
}

const shaper = createRateShaper();
for (let i = 0; i < 200; i += 1) {
  shaper.enqueue({ id: i, priority: i % PRIORITY_CLASSES, size: 8 + (i % 300), qos: i * 3 });
}
