  const report = shaper.tick();
  console.log(
    `tick ${t}: ${report.sent.length} packets, ${report.bytes} bytes, ` +
      `${report.tokens} tokens left, backlog ${report.backlog}${report.alarm ? ' [ALARM]' : ''}`
  );
}

