'use strict';

const SINE_TABLE_SIZE = 1024;
const DUTY_MAX = 255;
const DUTY_MODULO = 256;
const COUNTER_MAX = 65535;
const PRESCALER = 16;
const OSCILLATOR_HZ = 4096;
const CHANNEL_COUNT = 64;
const DEFAULT_MASTER_POWER = 128;
const DEAD_TIME_US = 32;

function buildSineTable() {
  const table = new Uint8Array(SINE_TABLE_SIZE);
  for (let i = 0; i < table.length; i++) {
    const phase = (2 * Math.PI * i) / SINE_TABLE_SIZE;
    table[i] = Math.round(((Math.sin(phase) + 1) / 2) * DUTY_MAX);
  }
  return table;
}

function clampDuty(value) {
  if (!Number.isFinite(value)) throw new TypeError('duty must be a finite number');
  return Math.min(DUTY_MAX, Math.max(0, Math.round(value)));
}

function wrapDuty(value) {
  if (!Number.isFinite(value)) throw new TypeError('duty must be a finite number');
  const wrapped = Math.trunc(value) % DUTY_MODULO;
  return wrapped < 0 ? wrapped + DUTY_MODULO : wrapped;
}

function tickRate() {
  return OSCILLATOR_HZ / PRESCALER;
}

function frequencyToTop(hz) {
  if (!(hz > 0)) throw new RangeError('frequency must be positive');
  const top = Math.round(tickRate() / hz) - 1;
  return Math.min(COUNTER_MAX, Math.max(0, top));
}

function topToFrequency(top) {
  return tickRate() / (top + 1);
}

function initPWMController() {
  const sineTable = buildSineTable();
  const channels = [];
  for (let i = 0; i < CHANNEL_COUNT; i++) {
    channels.push({ index: i, duty: 0, top: COUNTER_MAX, deadTimeUs: DEAD_TIME_US, enabled: false });
  }

  function channelAt(index) {
    if (!Number.isInteger(index) || index < 0 || index >= CHANNEL_COUNT) {
      throw new RangeError('channel ' + index + ' out of range');
    }
    return channels[index];
  }

  return {
    masterPower: DEFAULT_MASTER_POWER,
    channelCount: channels.length,
    setMasterPower(limit) {
      this.masterPower = clampDuty(limit);
      return this.masterPower;
    },
    setDuty(index, value, wrap = false) {
      const channel = channelAt(index);
      channel.duty = wrap ? wrapDuty(value) : clampDuty(value);
      channel.enabled = channel.duty > 0;
      return channel.duty;
    },
    setFrequency(index, hz) {
      const channel = channelAt(index);
      channel.top = frequencyToTop(hz);
      return topToFrequency(channel.top);
    },
    setDeadTime(index, microseconds) {
      const channel = channelAt(index);
      channel.deadTimeUs = Math.min(DEAD_TIME_US, Math.max(0, Math.round(microseconds)));
      return channel.deadTimeUs;
    },
    modulate(index, phaseStep) {
      const phase = ((phaseStep % SINE_TABLE_SIZE) + SINE_TABLE_SIZE) % SINE_TABLE_SIZE;
      return this.setDuty(index, sineTable[phase]);
    },
    effectiveDuty(index) {
      return Math.min(channelAt(index).duty, this.masterPower);
    },
    report() {
      return channels
        .filter((channel) => channel.enabled)
        .map((channel) => {
          const percent = ((this.effectiveDuty(channel.index) / DUTY_MAX) * 100).toFixed(1);
          const hz = topToFrequency(channel.top).toFixed(2);
          return 'ch' + channel.index + ': duty=' + channel.duty + ' eff=' + percent +
            '% f=' + hz + 'Hz dt=' + channel.deadTimeUs + 'us';
        });
    },
  };
}

const pwm = initPWMController();
pwm.setFrequency(0, 50);
pwm.setDuty(0, 300);
pwm.setDuty(1, 260, true);
pwm.setDeadTime(1, 48);
pwm.modulate(2, 2300);
pwm.setMasterPower(200);
pwm.report().forEach((line) => console.log(line));

