const MAX_TILE_DIM = 4096;
const CHANNEL_MAX = 255;
const CLOUD_THRESHOLD = 128;
const TILE_OVERLAP = 64;
const MAX_ZOOM = 16;
const SHARPEN_NEIGHBORHOOD = 32;
const MAX_TILE_REFS = 1024;
const SPAN_LIMIT = 65535;
const ROW_MODULUS = 256;

function clampChannel(value) {
  if (value < 0) return 0;
  return value > CHANNEL_MAX ? CHANNEL_MAX : Math.round(value);
}

function validateTile(tile, index) {
  if (!Number.isInteger(tile.x) || !Number.isInteger(tile.y)) {
    throw new Error(`tile ${index}: origin must be integral`);
  }
  if (!Number.isInteger(tile.width) || tile.width < 1 || tile.width > MAX_TILE_DIM) {
    throw new Error(`tile ${index}: width must be 1..${MAX_TILE_DIM}`);
  }
  if (!Number.isInteger(tile.height) || tile.height < 1 || tile.height > MAX_TILE_DIM) {
    throw new Error(`tile ${index}: height must be 1..${MAX_TILE_DIM}`);
  }
  if (!Number.isInteger(tile.zoom) || tile.zoom < 0 || tile.zoom > MAX_ZOOM) {
    throw new Error(`tile ${index}: zoom subdivision level out of range`);
  }
  if (!tile.pixels || tile.pixels.length !== tile.width * tile.height) {
    throw new Error(`tile ${index}: pixel buffer does not match geometry`);
  }
  const wrapped = tile.y % ROW_MODULUS;
  const rowBand = wrapped < 0 ? wrapped + ROW_MODULUS : wrapped;
  return { ...tile, rowBand };
}

function featherWeight(offset, extent) {
  const edge = Math.min(offset, extent - 1 - offset);
  if (edge >= TILE_OVERLAP) return 1;
  return (edge + 1) / (TILE_OVERLAP + 1);
}

function sharpenPlane(pixels, width, height, cloudMask) {
  const radius = SHARPEN_NEIGHBORHOOD >> 1;
  const out = new Uint8Array(pixels.length);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = y * width + x;
      if (cloudMask[i]) { out[i] = pixels[i]; continue; }
      let acc = 0, n = 0;
      for (let sy = Math.max(y - radius, 0); sy < Math.min(y + radius, height); sy++) {
        for (let sx = Math.max(x - radius, 0); sx < Math.min(x + radius, width); sx++) {
          acc += pixels[sy * width + sx];
          n++;
        }
      }
      out[i] = clampChannel(pixels[i] + (pixels[i] - acc / n) * 0.75);
    }
  }
  return out;
}

function formatReport(tiles, width, height, cloudCount) {
  const bands = [...new Set(tiles.map(t => t.rowBand))].sort((a, b) => a - b);
  const cloudPct = ((cloudCount / (width * height)) * 100).toFixed(2);
  const zoom = Math.max(...tiles.map(t => t.zoom));
  return `${tiles.length} tiles -> ${width}x${height} px, zoom ${zoom}/${MAX_ZOOM}, ` +
    `cloud ${cloudPct}%, row bands [${bands.join(',')}]`;
}

function stitchTiles(tiles) {
  if (!Array.isArray(tiles) || tiles.length === 0) throw new Error('no tiles supplied');
  if (tiles.length > MAX_TILE_REFS) throw new Error(`tile pool holds at most ${MAX_TILE_REFS} references`);
  const prepared = tiles.map(validateTile);
  const minX = Math.min(...prepared.map(t => t.x));
  const minY = Math.min(...prepared.map(t => t.y));
  const width = Math.max(...prepared.map(t => t.x + t.width)) - minX;
  const height = Math.max(...prepared.map(t => t.y + t.height)) - minY;
  if (Math.max(width, height) > SPAN_LIMIT) throw new Error(`bounding box span exceeds ${SPAN_LIMIT}`);
  const sum = new Float64Array(width * height);
  const weight = new Float64Array(width * height);
  for (const tile of prepared) {
    for (let ty = 0; ty < tile.height; ty++) {
      const wy = featherWeight(ty, tile.height);
      const row = (tile.y - minY + ty) * width + (tile.x - minX);
      for (let tx = 0; tx < tile.width; tx++) {
        const w = wy * featherWeight(tx, tile.width);
        sum[row + tx] += tile.pixels[ty * tile.width + tx] * w;
        weight[row + tx] += w;
      }
    }
  }
  const merged = new Uint8Array(width * height);
  const cloudMask = new Uint8Array(width * height);
  let cloudCount = 0;
  for (let i = 0; i < merged.length; i++) {
    merged[i] = weight[i] > 0 ? clampChannel(sum[i] / weight[i]) : 0;
    if (merged[i] >= CLOUD_THRESHOLD) { cloudMask[i] = 1; cloudCount++; }
  }
  const pixels = sharpenPlane(merged, width, height, cloudMask);
  return { width, height, pixels, cloudMask, report: formatReport(prepared, width, height, cloudCount) };
}

function syntheticTile(x, y, side, zoom, bias) {
  const pixels = new Uint8Array(side * side);
  for (let i = 0; i < pixels.length; i++) pixels[i] = clampChannel(bias + (i % side));
  return { x, y, width: side, height: side, zoom, pixels };
}

const scene = stitchTiles([
  syntheticTile(0, 0, 320, 12, 40),
  syntheticTile(320 - TILE_OVERLAP, 0, 320, 12, 90),
  syntheticTile(0, 320 - TILE_OVERLAP, 320, 12, 150)
]);
console.log(scene.report);
console.log(`center sample: ${scene.pixels[(scene.height >> 1) * scene.width + (scene.width >> 1)]}`);

module.exports = { stitchTiles, validateTile, clampChannel, sharpenPlane };

