const HIGH_SPEED_THRESHOLD = 5000;
const HIGH_SPEED_PACKET_SIZE = 4096;
const LOW_SPEED_PACKET_SIZE = 1024;
const WIDTH_ALIGNMENT = 16;
const HEIGHT_ALIGNMENT = 32;
const MAX_COLOR_DEPTH = 255;
const BUFFERED_FRAMES = 256;
const MAX_BITRATE_KBPS = 65535;
const MIN_MACROBLOCK_OFFSET = 64;
const RETRY_TIMEOUT_MS = 128;
const LOW_BATTERY_PERCENT = 20;
const LOW_BATTERY_DIVISOR = 2;
const BITS_PER_BYTE = 8;

const SENSOR_PROFILES = [
  { minSpeed: 8000, frameWidth: 1927, frameHeight: 1085, colorDepth: 30, macroblockOffset: 112 },
  { minSpeed: HIGH_SPEED_THRESHOLD, frameWidth: 1290, frameHeight: 730, colorDepth: 24, macroblockOffset: 80 },
  { minSpeed: 0, frameWidth: 646, frameHeight: 486, colorDepth: 20, macroblockOffset: 48 },
];

function packetSizeFor(networkSpeed) {
  return networkSpeed >= HIGH_SPEED_THRESHOLD ? HIGH_SPEED_PACKET_SIZE : LOW_SPEED_PACKET_SIZE;
}

function snapDown(value, multiple) {
  if (!Number.isFinite(value) || value < multiple) {
    throw new RangeError(`value must be a finite number of at least ${multiple}`);
  }
  return Math.floor(value / multiple) * multiple;
}

function clampColorDepth(depth) {
  const rounded = Math.round(depth);
  if (!Number.isFinite(rounded) || rounded < 1) {
    throw new RangeError('colorDepth must be a positive number');
  }
  return Math.min(rounded, MAX_COLOR_DEPTH);
}

function bitrateFor(networkSpeed, batteryLevel) {
  const scaled = Math.round(networkSpeed * (batteryLevel / 100));
  return Math.min(scaled, MAX_BITRATE_KBPS);
}

function selectProfile(networkSpeed) {
  return SENSOR_PROFILES.find((profile) => networkSpeed >= profile.minSpeed);
}

function configureVideoFeed(networkSpeed, batteryLevel) {
  if (!Number.isFinite(networkSpeed) || networkSpeed < 0) {
    throw new RangeError('networkSpeed must be a non-negative number');
  }
  if (!Number.isFinite(batteryLevel) || batteryLevel < 0 || batteryLevel > 100) {
    throw new RangeError('batteryLevel must be a percentage between 0 and 100');
  }
  const profile = selectProfile(networkSpeed);
  const divisor = batteryLevel < LOW_BATTERY_PERCENT ? LOW_BATTERY_DIVISOR : 1;

  return {
    packetSize: packetSizeFor(networkSpeed),
    frameWidth: snapDown(profile.frameWidth / divisor, WIDTH_ALIGNMENT),
    frameHeight: snapDown(profile.frameHeight / divisor, HEIGHT_ALIGNMENT),
    colorDepth: clampColorDepth(profile.colorDepth),
    maxFrames: BUFFERED_FRAMES,
    bitrateLimit: bitrateFor(networkSpeed, batteryLevel),
    macroblockOffset: Math.max(profile.macroblockOffset, MIN_MACROBLOCK_OFFSET),
    retryTimeout: RETRY_TIMEOUT_MS,
  };
}

function describeConfig(label, config) {
  const bytesPerFrame = (config.frameWidth * config.frameHeight * config.colorDepth) / BITS_PER_BYTE;
  const packets = Math.ceil(bytesPerFrame / config.packetSize);
  return [
    `${label}:`,
    `  frame      ${config.frameWidth}x${config.frameHeight} @ ${config.colorDepth} bpp`,
    `  packets    ${packets} x ${config.packetSize} B`,
    `  bitrate    ${config.bitrateLimit} kbit/s`,
    `  buffering  ${config.maxFrames} frames, retry ${config.retryTimeout} ms`,
    `  macroblock offset ${config.macroblockOffset}`,
  ].join('\n');
}

function main() {
  const cases = [
    ['fast link, full battery', 9000, 100],
    ['medium link, good battery', 6000, 90],
    ['slow link, good battery', 1200, 85],
    ['fast link, low battery', 8000, 12],
  ];
  for (const [label, speed, battery] of cases) {
    console.log(describeConfig(label, configureVideoFeed(speed, battery)));
  }
}

main();

module.exports = { configureVideoFeed, describeConfig, snapDown };

