'use strict';

var MAX_CHAPTERS = 256;
var MAX_MANIFEST_BYTES = 65535;
var MIN_COVER_WIDTH = 1024;
var MAX_TOC_DEPTH = 16;
var PARSE_BUFFER_BYTES = 4096;
var MAX_ID_LENGTH = 255;
var MAX_METADATA_ATTRS = 32;
var THUMB_SMALL = 64;
var THUMB_LARGE = 128;
var ITEM_OVERHEAD_BYTES = 32;
var ATTR_OVERHEAD_BYTES = 16;

function validateChapters(chapters) {
  if (!Array.isArray(chapters)) { throw new TypeError('chapters must be an array'); }
  if (chapters.length > MAX_CHAPTERS) { throw new RangeError('too many chapters: ' + chapters.length); }
  var items = [];
  chapters.forEach(function (chapter, index) {
    var id = String(chapter.id || 'chapter-' + index).slice(0, MAX_ID_LENGTH);
    items.push({
      id: id,
      href: 'text/' + id + '.xhtml',
      mediaType: 'application/xhtml+xml',
      bufferSize: Math.max(PARSE_BUFFER_BYTES, chapter.byteLength || 0)
    });
  });
  return items;
}

function normalizeThumbnail(width, height) {
  var longest = Math.max(width, height);
  var box = longest > THUMB_SMALL ? THUMB_LARGE : THUMB_SMALL;
  var scale = box / longest;
  return {
    width: Math.max(1, Math.round(width * scale)),
    height: Math.max(1, Math.round(height * scale)),
    box: box
  };
}

function validateImages(images) {
  var coverSeen = false;
  var items = images.map(function (img) {
    var item = { id: String(img.id).slice(0, MAX_ID_LENGTH), href: 'images/' + img.file, mediaType: img.mediaType };
    if (img.role === 'cover') {
      if (img.width < MIN_COVER_WIDTH) { throw new RangeError('cover too narrow: ' + img.width); }
      coverSeen = true;
    }
    item.dimensions = img.role === 'thumbnail' ? normalizeThumbnail(img.width, img.height) : { width: img.width, height: img.height };
    return item;
  });
  if (!coverSeen) { throw new Error('a cover image is required'); }
  return items;
}

function buildMetadataAttributes(metadata) {
  var names = Object.keys(metadata);
  if (names.length > MAX_METADATA_ATTRS) { throw new RangeError('metadata attributes capped at ' + MAX_METADATA_ATTRS); }
  return names.filter(function (name) {
    return metadata[name] !== undefined && metadata[name] !== null;
  }).map(function (name) {
    return { name: name, value: String(metadata[name]).slice(0, MAX_ID_LENGTH) };
  });
}

function estimateManifestSize(items, attributes) {
  var total = items.reduce(function (sum, item) {
    return sum + item.id.length + item.href.length + item.mediaType.length + ITEM_OVERHEAD_BYTES;
  }, PARSE_BUFFER_BYTES);
  total = attributes.reduce(function (sum, attr) {
    return sum + attr.name.length + attr.value.length + ATTR_OVERHEAD_BYTES;
  }, total);
  return Math.min(MAX_MANIFEST_BYTES, total);
}

function generateManifest(options) {
  var chapterItems = validateChapters(options.chapters);
  var manifest = chapterItems.concat(validateImages(options.images));
  var attributes = buildMetadataAttributes(options.metadata || {});
  var depth = Math.max(1, Math.floor(options.tocDepth || 1));
  return {
    attributes: attributes,
    manifest: manifest,
    spine: chapterItems.map(function (item) { return item.id; }),
    tocDepth: Math.min(depth, MAX_TOC_DEPTH),
    estimatedBytes: estimateManifestSize(manifest, attributes)
  };
}

function main() {
  var chapters = [];
  for (var i = 1; i <= 12; i++) {
    chapters.push({ id: 'ch' + i, byteLength: i * 900 });
  }
  var images = [
    { id: 'cover-img', file: 'cover.jpg', mediaType: 'image/jpeg', role: 'cover', width: 1600, height: 2400 },
    { id: 'thumb-1', file: 'thumb1.png', mediaType: 'image/png', role: 'thumbnail', width: 500, height: 250 },
    { id: 'thumb-2', file: 'thumb2.png', mediaType: 'image/png', role: 'thumbnail', width: 48, height: 60 }
  ];
  var metadata = { title: 'Sample Book', language: 'en', identifier: 'urn:uuid:0001' };
  var result = generateManifest({ chapters: chapters, images: images, metadata: metadata, tocDepth: 24 });
  console.log('items=' + result.manifest.length + ' spine=' + result.spine.length);
  console.log('tocDepth=' + result.tocDepth + ' bytes=' + result.estimatedBytes);
  result.manifest.forEach(function (item) {
    if (item.dimensions) {
      console.log(item.id + ': ' + item.dimensions.width + 'x' + item.dimensions.height);
    }
  });
}

module.exports = {
  generateManifest: generateManifest,
  validateChapters: validateChapters,
  validateImages: validateImages,
  normalizeThumbnail: normalizeThumbnail,
  buildMetadataAttributes: buildMetadataAttributes,
  estimateManifestSize: estimateManifestSize,
  main: main
};

if (require.main === module) { main(); }

