  const total = countNodes(ast);
  if (total > LIMITS.totalNodes) {
    throw new Error(`AST rejected: ${total} nodes exceeds ${LIMITS.totalNodes}`);
  }
  const report = [];
  const root = walk(ast, { list: 0, quote: 0 }, report);
  if (root.meta) root.meta = sanitizeMetadata(root.meta, report);
  return { ast: root, report, nodes: countNodes(root) };
}

function nest(type, levels, leaf) {
  let current = leaf;
  for (let i = 0; i < levels; i++) current = { type, children: [current] };
  return current;
}

const doc = {
  type: 'root',
  meta: { author: 'A'.repeat(400), ['x'.repeat(300)]: 'deep' },
  children: [
    { type: 'heading', depth: 40, children: [{ type: 'text', value: 'Title' }] },
    { type: 'paragraph', children: [{ type: 'text', value: 'p'.repeat(5000) }] },
    { type: 'paragraph', children: [{ type: 'inlineCode', value: 'c'.repeat(600) }] },
    { type: 'paragraph', children: [{ type: 'link', url: `http://x/${'q'.repeat(400)}`, children: [] }] },
    nest('list', 40, { type: 'text', value: 'deep item' }),
    nest('blockquote', 70, { type: 'text', value: 'deep quote' }),
  ],
};

const result = sanitize(doc);
console.log(`surviving nodes: ${result.nodes}`);
for (const line of result.report) console.log(` - ${line}`);
console.log(`heading depth now: ${result.ast.children[0].depth}`);

module.exports = { sanitize, sanitizeMetadata, countNodes, LIMITS };

