const MAX_WAREHOUSE_VOLUME = 65535;
const MAX_PALLET_WEIGHT = 1024;
const MAX_BOXES_PER_STACK = 16;
const MIN_SAFETY_MARGIN = 32;
const MAX_CATEGORIES_PER_AISLE = 256;
const MAX_TEMP_OFFSET = 255;
const ZONE_ARRAY_SIZE = 4096;
const CONTAINER_MODULUS_SMALL = 64;
const CONTAINER_MODULUS_LARGE = 128;

function validateVolume(totalVolume) {
  if (!Number.isFinite(totalVolume) || totalVolume <= 0) {
    throw new Error('Total warehouse volume must be a positive number');
  }
  if (totalVolume > MAX_WAREHOUSE_VOLUME) {
    throw new Error(`Volume limit exceeded: ${totalVolume} > ${MAX_WAREHOUSE_VOLUME} cubic units`);
  }
  return totalVolume;
}

function validateContainerLength(length) {
  if (length % CONTAINER_MODULUS_LARGE === 0) {
    return CONTAINER_MODULUS_LARGE;
  }
  if (length % CONTAINER_MODULUS_SMALL === 0) {
    return CONTAINER_MODULUS_SMALL;
  }
  throw new Error(`Container length ${length} must be a multiple of ${CONTAINER_MODULUS_SMALL} or ${CONTAINER_MODULUS_LARGE}`);
}

function clampTempOffset(offsetIndex) {
  const rounded = Math.round(offsetIndex);
  if (rounded < 0) return 0;
  return rounded > MAX_TEMP_OFFSET ? MAX_TEMP_OFFSET : rounded;
}

function planStacks(boxes) {
  const stacks = [];
  for (let i = 0; i < boxes.length; i += MAX_BOXES_PER_STACK) {
    stacks.push(boxes.slice(i, i + MAX_BOXES_PER_STACK));
  }
  return stacks;
}

function palletLoad(stack) {
  const weight = stack.reduce((sum, box) => sum + box.weight, 0);
  if (weight > MAX_PALLET_WEIGHT) {
    throw new Error(`Pallet overloaded: ${weight} kg exceeds ${MAX_PALLET_WEIGHT} kg`);
  }
  return weight;
}

function buildZoneMap(stacks) {
  const zones = new Uint16Array(ZONE_ARRAY_SIZE);
  stacks.forEach((stack, index) => {
    zones[index % ZONE_ARRAY_SIZE] = palletLoad(stack);
  });
  return zones;
}

function optimizePacking(request) {
  const volume = validateVolume(request.totalVolume);
  const modulus = validateContainerLength(request.containerLength);
  const categories = new Set(request.boxes.map((box) => box.category));
  if (categories.size > MAX_CATEGORIES_PER_AISLE) {
    throw new Error(`Aisle holds ${categories.size} categories, limit is ${MAX_CATEGORIES_PER_AISLE}`);
  }
  if (request.safetyMargin < MIN_SAFETY_MARGIN) {
    throw new Error(`Safety margin ${request.safetyMargin} is below ${MIN_SAFETY_MARGIN}`);
  }
  const stacks = planStacks(request.boxes);
  const zones = buildZoneMap(stacks);
  const used = stacks.reduce((sum, stack) => sum + palletLoad(stack), 0);
  const capacity = stacks.length * MAX_PALLET_WEIGHT;
  return {
    volume,
    lengthModulus: modulus,
    stackCount: stacks.length,
    categories: categories.size,
    tempOffset: clampTempOffset(request.tempOffset),
    totalWeight: used,
    heaviestZone: zones.reduce((best, load) => (load > best ? load : best), 0),
    fillRatio: capacity ? Number((used / capacity).toFixed(3)) : 0,
  };
}

function formatReport(plan) {
  return [
    `volume=${plan.volume}/${MAX_WAREHOUSE_VOLUME}`,
    `length multiple of ${plan.lengthModulus}`,
    `stacks=${plan.stackCount} (max ${MAX_BOXES_PER_STACK} boxes each)`,
    `categories=${plan.categories}`,
    `temp offset=${plan.tempOffset}`,
    `weight=${plan.totalWeight} kg, heaviest zone=${plan.heaviestZone} kg`,
    `fill ratio=${plan.fillRatio}`,
  ].join('\n');
}

function main() {
  const boxes = Array.from({ length: 70 }, (_, i) => ({
    id: `B${i}`,
    weight: 30 + (i % 24),
    category: `cat-${i % 12}`,
  }));
  const plan = optimizePacking({
    zone: 'north',
    totalVolume: 48000,
    containerLength: 640,
    safetyMargin: 41,
    tempOffset: 312,
    boxes,
  });
  console.log(formatReport(plan));
}

main();

module.exports = { optimizePacking, planStacks, palletLoad, clampTempOffset, formatReport };

