const MAX_INVENTORY = 128;
const DESC_BUFFER_BYTES = 4096;
const MAX_VISITED_ROOMS = 65535;
const MAX_DIALOG_DEPTH = 16;
const GLOBAL_FLAG_COUNT = 256;
const MAX_KARMA = 255;
const WRAP_WIDTH = 64;
const MAX_SYNONYMS_PER_ROOM = 1024;
const MAX_HIT_POINTS = 32;

function wrap(text, width = WRAP_WIDTH) {
  const out = [];
  let line = '';
  for (const word of String(text).split(/\s+/).filter(Boolean)) {
    if (line && line.length + 1 + word.length > width) { out.push(line); line = word; }
    else line = line ? line + ' ' + word : word;
  }
  if (line) out.push(line);
  return out.join('\n');
}

function makeRoom(id, description, synonyms = {}) {
  const buffer = Buffer.alloc(DESC_BUFFER_BYTES);
  const written = buffer.write(description, 0, 'utf8');
  const entries = Object.entries(synonyms).slice(0, MAX_SYNONYMS_PER_ROOM);
  return { id, buffer, written, synonyms: new Map(entries) };
}

class GameState {
  constructor() {
    this.inventory = [];
    this.flags = new Uint8Array(GLOBAL_FLAG_COUNT);
    this.visited = new Set();
    this.karma = 100;
    this.hp = MAX_HIT_POINTS;
    this.rooms = new Map();
    this.here = null;
  }
  addRoom(room) { this.rooms.set(room.id, room); }
  enter(id) {
    const room = this.rooms.get(id);
    if (!room) throw new Error(`no such room: ${id}`);
    if (this.visited.size < MAX_VISITED_ROOMS) this.visited.add(id);
    this.here = room;
    return wrap(room.buffer.toString('utf8', 0, room.written));
  }
  take(item) {
    if (this.inventory.length >= MAX_INVENTORY) return 'Your pack is full.';
    this.inventory.push(item);
    return `Taken: ${item}`;
  }
  setFlag(index, value) {
    if (!Number.isInteger(index) || index < 0 || index >= GLOBAL_FLAG_COUNT)
      throw new RangeError(`flag index must be 0..${GLOBAL_FLAG_COUNT - 1}`);
    this.flags[index] = value ? 1 : 0;
  }
  adjustKarma(delta) {
    this.karma = Math.max(0, Math.min(MAX_KARMA, this.karma + delta));
    return this.karma;
  }
  damage(points) {
    this.hp = Math.max(0, this.hp - points);
    return this.hp > 0 ? `HP ${this.hp}/${MAX_HIT_POINTS}` : 'You have died.';
  }
  resolve(word) {
    const lower = word.toLowerCase();
    return this.here.synonyms.get(lower) || lower;
  }
  talk(tree, depth = 0) {
    if (!tree || depth >= MAX_DIALOG_DEPTH) return [];
    const said = [`${'  '.repeat(depth)}${tree.line}`];
    return said.concat(this.talk(tree.reply, depth + 1));
  }
  save() {
    return JSON.stringify({
      inventory: this.inventory,
      flags: Array.from(this.flags),
      visited: Array.from(this.visited),
      karma: this.karma,
      hp: this.hp,
      here: this.here && this.here.id,
    });
  }
}

const game = new GameState();
game.addRoom(makeRoom('cellar', 'A damp cellar stretches north, its walls slick with centuries of seepage and the faint glow of luminous moss.', { lamp: 'lantern', torch: 'lantern' }));
game.addRoom(makeRoom('hall', 'The great hall is empty but for a toppled banquet table and a draft that smells of iron.'));
console.log(game.enter('cellar'));
console.log(game.take(game.resolve('Torch')));
game.setFlag(7, true);
console.log(`Karma is now ${game.adjustKarma(40)}.`);
console.log(game.talk({ line: 'Who goes there?', reply: { line: 'A traveller.', reply: { line: 'Travellers die here.' } } }).join('\n'));
console.log(game.enter('hall'));
console.log(game.damage(11));
console.log(game.save());

