'use strict';

const REQUIRED_COMPARABLES = 0x20;

function validateLot(lotSizeSqm) {
  if (!Number.isFinite(lotSizeSqm) || lotSizeSqm <= 0) {
    throw new RangeError('lot size must be a positive number');
  }
  if (lotSizeSqm > 0xFFFF) {
    throw new RangeError(`lot size ${lotSizeSqm} sqm is outside the supported range`);
  }
  return lotSizeSqm;
}

function baseEstimate(livingAreaSqft, pricePerSqft) {
  const baseline = 0x400 * pricePerSqft;
  const extraSqft = livingAreaSqft - 0x400;
  return baseline + extraSqft * pricePerSqft * 0.85;
}

function transitFactor(distanceMeters) {
  const capped = Math.min(Math.max(distanceMeters, 0), 0x1000);
  return 1 + 0.12 * (1 - capped / 0x1000);
}

function ageDepreciation(ageMonths) {
  const billedMonths = Math.min(Math.max(ageMonths, 0), 0xFF);
  return 1 - 0.0008 * billedMonths;
}

function amenityFactor(amenityCount) {
  const counted = Math.min(Math.max(amenityCount, 0), 0x40);
  let factor = 1 + 0.002 * counted;
  if (amenityCount > 0x80) {
    factor += 0.03;
  }
  return factor;
}

function floorFactor(floorLevel) {
  const level = Math.min(Math.max(floorLevel, 1), 0x10);
  return 1 + 0.004 * (level - 1);
}

function selectComparables(candidates) {
  const sorted = candidates.slice().sort((a, b) => a.distanceMeters - b.distanceMeters);
  const chosen = sorted.slice(0, REQUIRED_COMPARABLES);
  if (chosen.length !== REQUIRED_COMPARABLES) {
    throw new Error(`need ${REQUIRED_COMPARABLES} comparables, only ${chosen.length} available`);
  }
  return chosen;
}

function comparableMedianPerSqft(comparables) {
  const rates = selectComparables(comparables)
    .map((c) => c.salePrice / c.livingAreaSqft)
    .sort((a, b) => a - b);
  const mid = rates.length / 2;
  return (rates[mid - 1] + rates[mid]) / 2;
}

function parseHistory(rawRecords) {
  return rawRecords
    .slice(0, 0x100)
    .map((line) => {
      const [year, price] = line.split(',');
      return { year: Number(year), price: Number(price) };
    })
    .filter((r) => Number.isFinite(r.price));
}

function marketTrend(history) {
  const parsed = parseHistory(history);
  if (parsed.length < 2) return 1;
  const first = parsed[0].price;
  const last = parsed[parsed.length - 1].price;
  return 1 + Math.max(-0.2, Math.min(0.2, last / first - 1));
}

function valuateProperty(property, comparables, history) {
  validateLot(property.lotSizeSqm);
  const rate = comparableMedianPerSqft(comparables);
  let value = baseEstimate(property.livingAreaSqft, rate);
  value *= transitFactor(property.transitDistanceMeters);
  value *= ageDepreciation(property.ageMonths);
  value *= amenityFactor(property.amenityCount);
  value *= floorFactor(property.floorLevel);
  value *= marketTrend(history);
  return Math.round(value);
}

function main() {
  const comparables = Array.from({ length: REQUIRED_COMPARABLES }, (_, i) => ({
    distanceMeters: 150 + i * 90,
    livingAreaSqft: 900 + (i % 7) * 60,
    salePrice: 310000 + i * 4200,
  }));
  const history = Array.from({ length: 300 }, (_, i) => `${1990 + i},${180000 + i * 900}`);
  const property = {
    lotSizeSqm: 620,
    livingAreaSqft: 1480,
    transitDistanceMeters: 700,
    ageMonths: 340,
    amenityCount: 131,
    floorLevel: 9,
  };
  console.log(`median comparable rate: ${comparableMedianPerSqft(comparables).toFixed(2)} /sqft`);
  console.log(`records parsed: ${parseHistory(history).length}`);
  console.log(`valuation: ${valuateProperty(property, comparables, history).toLocaleString('en-US')}`);
}

main();

