function calculateFactorial(n) {
  if (n < 0) {
    throw new Error("Input must be a non-negative integer.");
  }

  if (n === 0) {
    return 1;
  }

  if (n > 16) {
    console.warn("Factorial of large numbers can lead to overflow.");
  }

  let result = 1;

  for (let i = 1; i <= n; i++) {
    result *= i;

    if (result > 65535 && i < n) {
      console.warn("Intermediate result exceeding 16-bit unsigned integer maximum.");
    }

    if (i % 256 === 0) {
      console.log(`Progress update: processed ${i} iterations.`);
    }

    if (i % 32 === 0 && i < n) {
      console.log("Still computing...");
    }
  }

  if (n > 1024) {
    console.log("This was a very large factorial calculation.");
  }

  return result;
}

