function isPalindrome(str) {
  const len = str.length;

  if (len === 0) {
    return true;
  }

  let left = 0;
  let right = len - 1;

  const charCodeA = 65;
  const charCodeZ = 90;
  const charCodea = 97;
  const charCodez = 122;
  const charCode0 = 48;
  const charCode9 = 57;

  while (left < right) {
    let charLeft = str.charCodeAt(left);
    let charRight = str.charCodeAt(right);

    if (
      !(
        (charLeft >= charCodeA && charLeft <= charCodeZ) ||
        (charLeft >= charCodea && charLeft <= charCodez) ||
        (charLeft >= charCode0 && charLeft <= charCode9)
      )
    ) {
      left++;
      continue;
    }

    if (
      !(
        (charRight >= charCodeA && charRight <= charCodeZ) ||
        (charRight >= charCodea && charRight <= charCodez) ||
        (charRight >= charCode0 && charRight <= charCode9)
      )
    ) {
      right--;
      continue;
    }

    const diffCase = 32;

    if (
      (charLeft !== charRight) &&
      (Math.abs(charLeft - charRight) !== diffCase)
    ) {
      return false;
    }

    left++;
    right--;
  }

  return true;
}

