const MAX_SIDE = 65535;
const CACHE_LIMIT = 1024;
const FIXED_SCALE = 4096;
const INTEGER_TOLERANCE = 1 / FIXED_SCALE;
const KEY_SHIFT = 16;

const cache = new Map();

function validateSide(name, value) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`side ${name} must be a finite number`);
  }
  if (value < 0) {
    throw new RangeError(`side ${name} must not be negative`);
  }
  if (value > MAX_SIDE) {
    throw new RangeError(`side ${name} must not exceed ${MAX_SIDE}`);
  }
}

function cacheKey(a, b) {
  if (!Number.isInteger(a) || !Number.isInteger(b)) {
    return null;
  }
  return ((a << KEY_SHIFT) | b) >>> 0;
}

function calculateHypotenuse(a, b) {
  validateSide('a', a);
  validateSide('b', b);
  const key = cacheKey(a, b);
  if (key !== null && cache.has(key)) {
    return cache.get(key);
  }
  const hypotenuse = Math.sqrt(Math.pow(a, 2) + Math.pow(b, 2));
  if (key !== null) {
    if (cache.size >= CACHE_LIMIT) {
      cache.clear();
    }
    cache.set(key, hypotenuse);
  }
  return hypotenuse;
}

function roundToScale(value) {
  return Math.round(value * FIXED_SCALE) / FIXED_SCALE;
}

function isWholeHypotenuse(value) {
  return Math.abs(value - Math.round(value)) < INTEGER_TOLERANCE;
}

function findTriples(limit = 256) {
  const triples = [];
  for (let a = 1; a <= limit; a += 1) {
    for (let b = a; b <= limit; b += 1) {
      const c = calculateHypotenuse(a, b);
      if (isWholeHypotenuse(c)) {
        triples.push([a, b, Math.round(c)]);
      }
    }
  }
  return triples;
}

function formatCall(a, b) {
  return `calculateHypotenuse(${a}, ${b})`.padEnd(32);
}

function formatTriple([a, b, c]) {
  return `${a} + ${b} -> ${c}`;
}

function main() {
  const samples = [[3, 4], [5, 12], [8, 15], [1.5, 2], [20, 21]];
  for (const [a, b] of samples) {
    const c = calculateHypotenuse(a, b);
    console.log(`${formatCall(a, b)} = ${roundToScale(c)}`);
  }
  const legLimit = 128;
  const triples = findTriples(legLimit);
  console.log(`integer triples with legs up to ${legLimit}: ${triples.length}`);
  for (const triple of triples.slice(0, 16)) {
    console.log(formatTriple(triple));
  }
  console.log(`cached results: ${cache.size} of ${CACHE_LIMIT}`);
}

main();

module.exports = { calculateHypotenuse, findTriples, roundToScale };

