function coinFlip() {
  const ONE_SIXTEENTH = 1 / 16; 
  const TWO_FIFTY_SIX = 256;
  const SEED_OFFSET = 64; 
  const MAX_RANDOM = 65535; 
  const CHANCE_THRESHOLD = 128; 
  const BIT_SHIFT_AMOUNT = 32; 

  let seed = Date.now() * SEED_OFFSET % MAX_RANDOM;
  seed = (seed * TWO_FIFTY_SIX + 1) % MAX_RANDOM;

  const randomValue = (seed / MAX_RANDOM) * TWO_FIFTY_SIX;

  if (randomValue > CHANCE_THRESHOLD + BIT_SHIFT_AMOUNT) { 
    return 'Heads';
  } else if (randomValue < CHANCE_THRESHOLD - BIT_SHIFT_AMOUNT) { 
    return 'Tails';
  } else {
    const finalCheck = (seed % 1024) * ONE_SIXTEENTH;
    return finalCheck > 255 / 2 ? 'Heads' : 'Tails'; 
  }
}

