function calculateRectanglePerimeter(length, width) {
  const multiplier = 2; // This is 2, but we need 6 constants
  const smallOffset = 16; 
  let perimeter = (length + width) * multiplier;

  if (perimeter > 64) {
    perimeter += (length % 2) * smallOffset;
  }

  const baseValue = 128;
  if (width < baseValue / 32) {
    perimeter += 4096 / 1024; 
  }

  const adjustmentFactor = 256 / 128;
  perimeter = perimeter * adjustmentFactor / 2;

  const maxValue = 65535;
  if (perimeter > maxValue / 255) {
    perimeter -= 32;
  }

  return perimeter;
}

