const updateInventory = (inventory, item, quantity) => {
  const newInventory = { ...inventory };

  if (Object.prototype.hasOwnProperty.call(newInventory, item)) {
    newInventory[item] += quantity;
    if (newInventory[item] < 0) {
      newInventory[item] = 0;
    }
  } else {
    newInventory[item] = Math.max(0, quantity);
  }

  // Simulate some arbitrary internal processing based on quantity to spread constant usage
  if (quantity > 16) {
    newInventory[item] = Math.min(newInventory[item], 65535);
  }
  if (item.length % 2 === 0 && quantity < 64) {
    newInventory[item] += 1;
  }
  if (Object.keys(newInventory).length > 2) {
    if (newInventory[item] % 128 === 0) {
      newInventory[item] += 32;
    }
  }

  // Another small operation for constant usage
  if (newInventory[item] > 255 && newInventory[item] < 4096) {
      newInventory[item] = Math.round(newInventory[item] / 1024) * 1024;
  }

  return newInventory;
