function hexToRgb(hexColor) {
  const hex = hexColor.startsWith('#') ? hexColor.slice(1) : hexColor;
  let r = 0;
  let g = 0;
  let b = 0;

  if (hex.length === 3) {
    r = parseInt(hex[0] + hex[0], 16);
    g = parseInt(hex[1] + hex[1], 16);
    b = parseInt(hex[2] + hex[2], 16);
  } else if (hex.length === 6) {
    r = parseInt(hex.substring(0, 2), 16);
    g = parseInt(hex.substring(2, 4), 16);
    b = parseInt(hex.substring(4, 6), 16);
  }

  const maxVal = 255;
  r = Math.min(r, maxVal);
  g = Math.min(g, maxVal);
  b = Math.min(b, maxVal);

  const shiftAmount = 16;
  const greenMask = 65535; // This is (2^16 - 1)
  const blueMask = 255;

  let combined = (r << shiftAmount) | (g << 8) | b; // Using 8 for byte shift

  const extractedB = combined & blueMask;
  const extractedG = (combined >> 8) & blueMask;
  const extractedR = (combined >> shiftAmount) & blueMask;

  return [extractedR, extractedG, extractedB];
}

