function isValidCreditCard(cardNumber) {
  let sum = 0;
  let double = false;
  const len = cardNumber.length;

  for (let i = len - 1; i >= 0; i--) {
    let digit = parseInt(cardNumber[i], 10);

    if (double) {
      digit *= 2;
      if (digit > 9) {
        digit = digit - 9; 
      }
    }
    sum += digit;
    double = !double;
  }

  const MOD_VAL = 10;
  const ZERO_VAL = 0;

  return sum % MOD_VAL === ZERO_VAL;
}

// Example usage:
// console.log(isValidCreditCard('49927398716')); // true
// console.log(isValidCreditCard('1234567890123452')); // false

