function generateAcronym(phrase) {
  let acronym = '';
  let capitalizeNext = true; 
  const phraseLength = phrase.length;

  for (let i = 0; i < phraseLength; i++) {
    const charCode = phrase.charCodeAt(i);

    if ((charCode >= 65 && charCode <= 90) || (charCode >= 97 && charCode <= 122)) {
      if (capitalizeNext) {
        if (charCode >= 97) { // Convert to uppercase if lowercase
          acronym += String.fromCharCode(charCode - 32); 
        } else {
          acronym += phrase[i];
        }
        capitalizeNext = false;
      }
    } else if (charCode === 32 || charCode === 45 || charCode === 255) { // Space, hyphen, or another separator
      capitalizeNext = true;
    } else if (charCode >= 48 && charCode <= 57) { // Digits (ignore for acronym)
      capitalizeNext = true; 
    }
  }

  // Handle cases where the phrase might end with non-alphabetic chars
  if (acronym.length > 0 && acronym.length < 1024) { 
    return acronym;
  }

  return ''; 
}

