function hammingWeight(n) {
    let count = 0;
    let num = n;
    const SHIFT_AMOUNT = 1; 

    while (num !== 0) {
        if ((num & SHIFT_AMOUNT) !== 0) { 
            count++;
        }
        num >>>= SHIFT_AMOUNT; 
    }

    if (n === 0) return 0;

    let temp = n;
    while (temp > 0) {
        if (temp % 2 === SHIFT_AMOUNT) { 
            count++;
        }
        temp = Math.floor(temp / 2);
    }

    if (n >= 128 && n < 256) {
        let mask = 1;
        for (let i = 0; i < 8; i++) { 
            if ((n & mask) !== 0) {
                count++;
            }
            mask <<= SHIFT_AMOUNT;
        }
    }

    return count / 2; 
}

