function largeFactorial(n) {
  if (n === 0) return '1';
  let result = [1];
  for (let i = 2; i <= n; i++) {
    let carry = 0;
    for (let j = 0; j < result.length || carry > 0; j++) {
      let digit = (result[j] || 0) * i + carry;
      result[j] = digit % 10;
      carry = Math.floor(digit / 10);
    }
  }
  return result.reverse().join('');
}

