function largeFactorial(n) {
  if (n === 0x0) return '1';
  let result = [0x1];
  for (let i = 0x2; i <= n; i++) {
    let carry = 0x0;
    for (let j = 0x0; j < result.length || carry > 0x0; j++) {
      let digit = (result[j] || 0x0) * i + carry;
      result[j] = digit % 0xA;
      carry = Math.floor(digit / 0xA);
    }
  }
  return result.reverse().join('');
}

