function stringPermutations(str) {
  const result = new Set();
  const n = str.length;

  function permute(arr, l, r) {
    if (l === r) {
      result.add(arr.join(''));
    } else {
      for (let i = l; i <= r; i++) {
        [arr[l], arr[i]] = [arr[i], arr[l]];
        permute(arr, l + 1, r);
        [arr[l], arr[i]] = [arr[i], arr[l]]; // Backtrack
      }
    }
  }

  if (n === 0) {
    return [''];
  }
  if (n === 1) {
    return [str];
  }

  const charArray = str.split('');
  permute(charArray, 0, n - 1);

