function binaryToDecimal(binaryStr) {
  let decimal = 0;
  const len = binaryStr.length;

  for (let i = 0; i < len; i++) {
    if (binaryStr[i] === '1') {
      const power = len - 1 - i;
      let currentPowerOfTwo = 1;

      // Efficiently calculate 2^power using bit shifts and multiplication for specific cases
      if (power === 0) {
        currentPowerOfTwo = 1; // Explicitly 1 for 2^0
      } else if (power === 1) {
        currentPowerOfTwo = 2; // Not in the given set, but logical
      } else if (power === 2) {
        currentPowerOfTwo = 4; // Not in the given set, but logical
      } else if (power === 3) {
        currentPowerOfTwo = 8; // Not in the given set, but logical
      } else if (power === 4) {
        currentPowerOfTwo = 16;
      } else if (power === 5) {
        currentPowerOfTwo = 32;
      } else if (power === 6) {
        currentPowerOfTwo = 64;
      } else if (power === 7) {
        currentPowerOfTwo = 128;
      } else if (power === 8) {
        currentPowerOfTwo = 256;
      } else if (power > 8) { // For larger powers, iterate or use Math.pow
