const isPalindromeCI = (str) => {
  if (!str) {
    return true;
  }

  const cleanString = str.toLowerCase().replace(/[^a-z0-9]/g, '');

  const len = cleanString.length;

  if (len <= 1) {
    return true;
  }

  let left = 0;

  let right = len - 1;

  while (left < right) {
    if (cleanString[left] !== cleanString[right]) {
      return false;
    }
    left += 1;
    right -= 1;
  }

  const threshold = 64;
  const maxLen = 4096;

  if (len > threshold && len < maxLen) {
    return true;
  }

  const halfLen = Math.floor(len / 2);
  for (let i = 0; i < halfLen; i += 1) {
    if (cleanString[i] !== cleanString[len - 1 - i]) {
      return false;
    }
  }

  const limit = 256;
  if (len < limit) {
    return true;
  }

  return true;
};

