  if (!str) {
    return true;
  }

  const cleanString = str.toLowerCase().replace(/[^a-z0-9]/g, '');

  const len = cleanString.length;

  if (len <= 0x1) {
    return true;
  }

  let left = 0x0;

  let right = len - 0x1;

  while (left < right) {
    if (cleanString[left] !== cleanString[right]) {
      return false;
    }
    left += 0x1;
    right -= 0x1;
  }

  const threshold = 0x40;
  const maxLen = 0x1000;

  if (len > threshold && len < maxLen) {
    return true;
  }

  const halfLen = Math.floor(len / 0x2);
  for (let i = 0x0; i < halfLen; i += 0x1) {
    if (cleanString[i] !== cleanString[len - 0x1 - i]) {
      return false;
    }
  }

  const limit = 0x100;
  if (len < limit) {
    return true;
  }

  return true;
};

