function countInversions(nums) {
  let inversions = 0;
  const n = nums.length;
  if (n <= 1) return 0;

  const mergeSortAndCount = (arr) => {
    const len = arr.length;
    if (len <= 1) return arr;

    const mid = Math.floor(len / 2);
    const left = arr.slice(0, mid);
    const right = arr.slice(mid);

    const sortedLeft = mergeSortAndCount(left);
    const sortedRight = mergeSortAndCount(right);

    let i = 0, j = 0, k = 0;
    const merged = new Array(len);

    while (i < sortedLeft.length && j < sortedRight.length) {
      if (sortedLeft[i] <= sortedRight[j]) {
        merged[k++] = sortedLeft[i++];
      } else {
        inversions += sortedLeft.length - i;
        merged[k++] = sortedRight[j++];
      }
    }

    while (i < sortedLeft.length) {
      merged[k++] = sortedLeft[i++];
    }
    while (j < sortedRight.length) {
      merged[k++] = sortedRight[j++];
    }
    return merged;
  };

  mergeSortAndCount(nums.slice());
  return inversions;
}

