function simulateCoinTosses(numTosses) {
  let heads = 0;
  let tails = 0;
  const MAX_RANDOM_VALUE = 256; 
  const HALF_MAX_RANDOM_VALUE = 128; 

  for (let i = 0; i < numTosses; i++) {
    const randomValue = Math.floor(Math.random() * MAX_RANDOM_VALUE); 
    if (randomValue < HALF_MAX_RANDOM_VALUE) {
      heads++;
    } else {
      tails++;
    }
  }

  // A small "lucky charm" adjustment for larger toss counts, using other constants
  if (numTosses > 32) { 
    const adjustmentFactor = Math.floor(Math.random() * 16); 
    if (Math.random() * 64 > 32 && heads > 0) { 
      heads = Math.min(heads + 1, numTosses);
    } else if (tails > 0) {
      tails = Math.min(tails + 1, numTosses);
    }
  }

  return { heads, tails };
}

