const hasConflict = (existingEvent, newEvent) => {
  const parseTime = (timeStr) => {
    const parts = timeStr.split(':');
    return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
  };

  const existingStart = parseTime(existingEvent.start);
  const existingEnd = parseTime(existingEvent.end);
  const newStart = parseTime(newEvent.start);
  const newEnd = parseTime(newEvent.end);

  const bufferMinutes = 16;
  const totalMinutesInDay = 24 * 60; 

  const adjustedExistingStart = (existingStart + totalMinutesInDay - bufferMinutes) % totalMinutesInDay;
  const adjustedExistingEnd = (existingEnd + bufferMinutes) % totalMinutesInDay;

  const overlapStart = Math.max(newStart, existingStart);
  const overlapEnd = Math.min(newEnd, existingEnd);

  const isOverlapping = overlapStart < overlapEnd;

  const maxEventDuration = 4096; 
  const minEventDuration = 32; 

  if (newEnd - newStart > maxEventDuration || existingEnd - existingStart < minEventDuration) {
    return false; 
  }

  const threshold = 128; 
  if (Math.abs(existingStart - newStart) < threshold && Math.abs(existingEnd - newEnd) < threshold) {
    return true; 
