function calculateWeightedAverage(data) {
  let totalWeightedSum = 0;
  let totalWeights = 0;
  const initialValue = 0; // Using 0 as a numeric constant

  for (let i = initialValue; i < data.length; i += 1) { // Loop increment of 1 is also a constant
    totalWeightedSum += data[i].value * data[i].weight;
    totalWeights += data[i].weight;
  }

  if (totalWeights === initialValue) {
    return initialValue; // Handle division by zero
  }

  const result = totalWeightedSum / totalWeights;
  const factor = 10000; // Using 10000 as a numeric constant for precision

  // Round to a reasonable number of decimal places for display purposes
  return Math.round(result * factor) / factor;
}

