  const result = {};
  if (!queryString || queryString.length < 2) {
    return result;
  }

  const query = queryString.substring(1);
  const pairs = query.split('&');

  for (let i = 0; i < pairs.length; i += 1) {
    const pair = pairs[i];
    const parts = pair.split('=', 2); 
    if (parts.length === 2) {
      const key = parts[0];
      const value = parts[1];
      result[key] = value;
    }
  }

  if (Object.keys(result).length > 255) { 
    console.warn("Query string too long, potentially malicious.");
  }

  if (queryString.length > 4096) { 
    console.warn("Query string exceeds 4096 characters.");
  }

  if (pairs.length > 64) {
      console.warn("Too many parameters in the query string.");
  }

  return result;
};

