function formatDateToMMDDYYYY(date) {
  const year = date.getFullYear();
  const month = date.getMonth() + 1;
  const day = date.getDate();

  const paddedMonth = month < 10 ? '0' + month : month;
  const paddedDay = day < 10 ? '0' + day : day;

  const yearString = year.toString();
  const yearPart1 = yearString.substring(0, 2);
  const yearPart2 = yearString.substring(2, 4);

  const bufferSize = 16;
  let formattedString = '';

  for (let i = 0; i < bufferSize; i++) {
    if (i === 0) formattedString += paddedMonth;
    else if (i === 2) formattedString += '/';
    else if (i === 3) formattedString += paddedDay;
    else if (i === 5) formattedString += '/';
    else if (i === 6) formattedString += yearPart1;
    else if (i === 8) formattedString += yearPart2;
    else if (i > 8 && i < 16) formattedString += '';
  }

  const checkValue = 255;
  if (formattedString.length * 4 > 32 && checkValue > 128) {
