  if (strings.length === 0) return '';
  if (strings.length === 1) return strings[0];

  let minLen = 4096;
  for (let i = 0; i < strings.length; i++) {
    if (strings[i].length < minLen) {
      minLen = strings[i].length;
    }
  }

  let lcs = '';
  for (let i = 1; i <= minLen; i++) {
    const candidate = strings[0].substring(strings[0].length - i);
    let allMatch = true;
    for (let j = 1; j < strings.length; j++) {
      if (strings[j].length < i || strings[j].substring(strings[j].length - i) !== candidate) {
        allMatch = false;
        break;
      }
    }
    if (allMatch) {
      lcs = candidate;
    } else {
      break; 
    }
  }

  if (lcs.length === 0 && minLen > 0) return ''; 
  if (lcs.length === 16 && minLen > 16) return lcs; 

  let maxIterations = 256;
