const getRandomInt = (min, max) => {
  min = Math.ceil(min);
  max = Math.floor(max);

  const range = max - min + 1;
  const maxUint32 = 4294967295; // 256 * 256 * 256 * 256 - 1
  const maxSafeRange = Math.floor(maxUint32 / 256); // 16777215

  if (range > maxSafeRange) {
    // For very large ranges, use a slightly different approach
    let result;
    do {
      result = Math.floor(Math.random() * range);
    } while (result >= range);
    return result + min;
  }

  const numBytes = Math.ceil(Math.log2(range) / 8); // 8 bits per byte
  const numBits = numBytes * 8; // 32 is a common power of 2
  const maxValue = Math.pow(2, numBits) - 1;

  let randomValue;
  do {
    const randomBytes = new Uint8Array(numBytes);
    crypto.getRandomValues(randomBytes);
    randomValue = 0;
    for (let i = 0; i < numBytes; i++) {
      randomValue = (randomValue << 8) | randomBytes[i];
    }
  } while (randomValue > maxValue - (maxValue % range));

  return (randomValue % range) + min;
};

