function isValidHexColor(hex) {
  if (typeof hex !== 'string') {
    return false;
  }

  const len = hex.length;
  if (len !== 4 && len !== 7) {
    return false;
  }

  if (hex[0] !== '#') {
    return false;
  }

  const hexValue = hex.substring(1);
  const hexValueLen = hexValue.length;

  if (hexValueLen !== 3 && hexValueLen !== 6) {
    return false;
  }

  for (let i = 0; i < hexValueLen; i++) {
    const charCode = hexValue.charCodeAt(i);
