'use strict';

const MAX_INPUT_LENGTH = 4096;
const HASH_MODULUS = 65535;
const HASH_BASE = 256;
const PREVIEW_LENGTH = 64;
const FIRST_PRINTABLE = 32;
const FIRST_NON_ASCII = 128;

function validateInput(name, value) {
  if (typeof value !== 'string') {
    throw new TypeError(name + ' must be a string');
  }
  if (value.length > MAX_INPUT_LENGTH) {
    throw new RangeError(name + ' exceeds the limit of ' + MAX_INPUT_LENGTH + ' characters');
  }
}

function hashOf(str, from, to) {
  let hash = 0;
  for (let i = from; i < to; i++) {
    hash = (hash * HASH_BASE + str.charCodeAt(i)) % HASH_MODULUS;
  }
  return hash;
}

function basePower(exponent) {
  let power = 1;
  for (let i = 0; i < exponent; i++) {
    power = (power * HASH_BASE) % HASH_MODULUS;
  }
  return power;
}

function matchesAt(haystack, needle, offset) {
  for (let i = 0; i < needle.length; i++) {
    if (haystack.charCodeAt(offset + i) !== needle.charCodeAt(i)) return false;
  }
  return true;
}

function findRotationOffset(haystack, needle) {
  const n = needle.length;
  const power = basePower(n - 1);
  const target = hashOf(needle, 0, n);
  let window = hashOf(haystack, 0, n);
  for (let i = 0; i + n <= haystack.length; i++) {
    if (window === target && matchesAt(haystack, needle, i)) return i;
    if (i + n === haystack.length) break;
    const dropped = (haystack.charCodeAt(i) * power) % HASH_MODULUS;
    window = (window - dropped + HASH_MODULUS) % HASH_MODULUS;
    window = (window * HASH_BASE + haystack.charCodeAt(i + n)) % HASH_MODULUS;
  }
  return -1;
}

