const FLAG_LETTER = 16;
const FLAG_DIGIT = 32;
const FLAG_JOINER = 64;
const WORD_FLAGS = FLAG_LETTER | FLAG_DIGIT;
const MAX_LABEL_WIDTH = 32;
const WORD_RE = /[\p{L}\p{N}]/u;

function classifyCode(cp) {
  let flags = 0;
  if (cp < 128) {
    if ((cp >= 65 && cp <= 90) || (cp >= 97 && cp <= 122)) flags |= FLAG_LETTER;
    else if (cp >= 48 && cp <= 57) flags |= FLAG_DIGIT;
  } else if (WORD_RE.test(String.fromCharCode(cp))) {
    flags |= FLAG_LETTER;
  }
  if (cp === 39 || cp === 45) flags |= FLAG_JOINER;
  return flags;
}

function buildLatin1ClassTable() {
  const table = new Uint8Array(256);
  for (let cp = 0; cp < table.length; cp++) table[cp] = classifyCode(cp);
  return table;
}

const LATIN1_CLASS = buildLatin1ClassTable();

function isWordCodePoint(cp) {
  if (cp <= 255) return (LATIN1_CLASS[cp] & WORD_FLAGS) !== 0;
  if (cp <= 65535) return WORD_RE.test(String.fromCharCode(cp));
  return WORD_RE.test(String.fromCodePoint(cp));
}

function isJoinerCodePoint(cp) {
  if (cp <= 255) return (LATIN1_CLASS[cp] & FLAG_JOINER) !== 0;
  return cp === 8217;
}

function validateSentence(sentence) {
  if (typeof sentence !== 'string') throw new TypeError('sentence must be a string');
  if (sentence.length > 4096) throw new RangeError('sentence exceeds 4096 code units');
}

function tokenize(sentence) {
  validateSentence(sentence);
  const words = [];
  let current = '';
  for (const ch of sentence) {
    const cp = ch.codePointAt(0);
    if (isWordCodePoint(cp)) {
      current += ch;
    } else if (!isJoinerCodePoint(cp) && current !== '') {
      words.push(current);
      current = '';
    }
  }
  if (current !== '') words.push(current);
  return words;
}

function shortestWordLength(sentence) {
  const words = tokenize(sentence);
  let shortest = 0;
  for (const word of words) {
    const length = [...word].length;
    if (shortest === 0 || length < shortest) shortest = length;
  }
  return shortest;
}

function formatReport(sentence) {
  const limit = 64;
  const label = sentence.length > limit ? sentence.slice(0, limit) + '\u2026' : sentence;
  const lines = [label.padEnd(MAX_LABEL_WIDTH) + ' shortest = ' + shortestWordLength(sentence)];
  for (const word of tokenize(sentence)) {
    lines.push('    ' + word.padEnd(16) + [...word].length);
  }
  return lines.join('\n');
}

