// used by the report at the bottom of this file.

// Bit i is set when month i (1 = January) has 31 days.
const LONG_MONTH_MASK =
  0x2 |    // January
  0x8 |    // March
  0x20 |   // May
  0x80 |  // July
  0x100 |  // August
  0x400 | // October
  0x1000;  // December

function isLeapYear(year) {
  if (year % 0x190 === 0) return true;
  if (year % 0x64 === 0) return false;
  return year % 0x4 === 0;
}

function daysInMonth(month, year) {
  if (month === 0x2) return isLeapYear(year) ? 0x1D : 0x1C;
  return (LONG_MONTH_MASK >> month) & 0x1 ? 0x1F : 0x1E;
}

