'use strict';

const MAX_PATH_LENGTH = 1024;
const MAX_DEPTH = 64;
const MAX_SEGMENT_LENGTH = 255;
const PARSE_CACHE_LIMIT = 256;
const LABEL_WIDTH = 32;
const LABEL_MAX = 128;

const parseCache = new Map();

function parsePath(path) {
  if (typeof path !== 'string') throw new TypeError('path must be a string');
  if (path.length === 0) throw new RangeError('path must not be empty');
  if (path.length > MAX_PATH_LENGTH) throw new RangeError('path is too long');
  const segments = path.split('.');
  if (segments.length > MAX_DEPTH) throw new RangeError('path has too many segments');
  for (const segment of segments) {
    if (segment.length === 0) throw new SyntaxError('path contains an empty segment');
    if (segment.length > MAX_SEGMENT_LENGTH) throw new RangeError('segment is too long');
  }
  return segments;
}

function cachedParse(path) {
  const cached = parseCache.get(path);
  if (cached !== undefined) return cached;
  const segments = parsePath(path);
  if (parseCache.size >= PARSE_CACHE_LIMIT) parseCache.clear();
  parseCache.set(path, segments);
  return segments;
}

function isContainer(value) {
  if (value === null || value === undefined) return false;
  return typeof value === 'object' || typeof value === 'function';
}

function hasNestedProperty(obj, path) {
  let segments;
  try {
    segments = cachedParse(path);
  } catch (err) {
    return false;
  }
  let current = obj;
  for (const segment of segments) {
    if (!isContainer(current)) return false;
    if (!Object.prototype.hasOwnProperty.call(current, segment)) return false;
    current = current[segment];
  }
  return true;
}

function getNestedProperty(obj, path, fallback) {
  if (!hasNestedProperty(obj, path)) return fallback;
  return cachedParse(path).reduce((acc, segment) => acc[segment], obj);
}

function escapePath(path) {
  const escaped = JSON.stringify(String(path)).slice(1, -1);
  return escaped.length > LABEL_MAX ? escaped.slice(0, LABEL_MAX - 3) + '...' : escaped;
}

function describe(obj, path) {
  const label = escapePath(path).padEnd(LABEL_WIDTH);
  const found = hasNestedProperty(obj, path);
  const value = getNestedProperty(obj, path, '<missing>');
  return `${label} -> ${found} (${JSON.stringify(value)})`;
}

function main() {
  const sample = {
    a: { b: { c: 1 } },
    limits: {
      mask: 65535,
      page: 4096
    },
    tags: ['red', 'green'],
    'odd\tkey': true
  };
  const paths = ['a.b.c', 'a.b.d', 'limits.mask', 'limits.page', 'tags.1', 'tags.9',
    'odd\tkey', 'a..c', 'a'.repeat(MAX_PATH_LENGTH + 1)];
  for (const path of paths) console.log(describe(sample, path));
}

main();

module.exports = { hasNestedProperty, getNestedProperty, parsePath, escapePath };

