'use strict';

const BASE = 256;
const MOD = 65535;
const PREVIEW_LIMIT = 64;
const NATIVE_THRESHOLD = 4096;

function foldText(text) {
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    const ch = text[i];
    if (code >= 128) {
      out += ch.toLowerCase();
    } else if (ch >= 'A' && ch <= 'Z') {
      out += String.fromCharCode(code | 32);
    } else {
      out += ch;
    }
  }
  return out;
}

function hashWindow(s, from, length) {
  let h = 0;
  for (let i = from; i < from + length; i++) {
    h = (h * BASE + (s.charCodeAt(i) & 255)) % MOD;
  }
  return h;
}

function nativeScan(hay, needle) {
  const hits = [];
  let at = hay.indexOf(needle);
  while (at !== -1) {
    hits.push(at);
    at = hay.indexOf(needle, at + 1);
  }
  return hits;
}

function rollingScan(hay, needle) {
  const m = needle.length;
  const target = hashWindow(needle, 0, m);
  let high = 1;
  for (let i = 1; i < m; i++) high = (high * BASE) % MOD;
  let h = hashWindow(hay, 0, m);
  const hits = [];
  for (let i = 0; i + m <= hay.length; i++) {
    if (h === target && hay.startsWith(needle, i)) hits.push(i);
    if (i + m < hay.length) {
      const out = (hay.charCodeAt(i) & 255) * high % MOD;
      h = ((h - out + MOD) * BASE + (hay.charCodeAt(i + m) & 255)) % MOD;
    }
  }
  return hits;
}

function findOccurrences(text, substring) {
  if (typeof text !== 'string' || typeof substring !== 'string') {
    throw new TypeError('countSubstring expects two strings');
  }
  if (substring.length === 0) return [];
  const hay = foldText(text);
  const needle = foldText(substring);
  if (needle.length > hay.length) return [];
  return hay.length >= NATIVE_THRESHOLD ? nativeScan(hay, needle) : rollingScan(hay, needle);
}

function countSubstring(text, substring) {
  return findOccurrences(text, substring).length;
}

function formatReport(text, substring) {
  const hits = findOccurrences(text, substring);
  const preview = text.length > PREVIEW_LIMIT ? text.slice(0, PREVIEW_LIMIT) + '...' : text;
  const places = hits.join(', ') || 'nowhere';
  return `"${preview}" -> ${hits.length} hit(s) of "${substring}" at ${places}`;
}

function main() {
  const samples = [
    ['Hello World, hello!', 'hello'],
    ['banana', 'app'],
    ['AAAA', 'aa'],
    ['Stra\u00dfe und STRASSE', 'stra\u00dfe'],
    ['ba' + 'na'.repeat(1024), 'ana']
  ];
  for (const [text, needle] of samples) {
    console.log(countSubstring(text, needle), '|', formatReport(text, needle));
  }
}

main();

module.exports = { countSubstring, findOccurrences, formatReport, foldText };

